    #[test]
    fn retained_owned_server_keeps_qualification_until_physical_proof() {
        for historical in [false, true] {
            let scene = if historical {
                crate::semantic::successor_review_tests::Scene::historical(false)
            } else {
                crate::semantic::successor_review_tests::Scene::new(false)
            };
            let manifest = scene.manifest();
            let binding = manifest.global_profile_binding.as_ref().unwrap();
            let mut session = scene.worker_bootstrap(4, false, true);
            session.app_server_socket = scene.state_root().join("absent-app.sock");
            let executable = &binding.launch_snapshot.executable_identity;
            session.dedicated_server = Some(DedicatedServerBootstrap {
                socket_path: session.app_server_socket.clone(),
                argv: caller_workspace_argv(manifest),
                cwd: session.cwd.clone(),
                environment: binding.launch_snapshot.sanitized_environment.clone(),
                log_path: scene.state_root().join("startup-refusal.log"),
                executable_device: executable.device,
                executable_inode: executable.inode,
                executable_sha256: executable.sha256.clone(),
                server_epoch: 1,
            });
            assert!(!session.app_server_socket.exists());
            let mut worker = identity();
            worker.run_id = manifest.run_id;
            worker.workspace_id = manifest.workspace_id.clone();
            worker.run_generation = 1;
            worker.uid = DarwinSystem.current_uid();
            let mut child = std::process::Command::new("/usr/bin/true").spawn().unwrap();
            let pid = child.id();
            child.wait().unwrap();
            // The owned process is already reaped and the socket is absent.
            // This tests the admission cut before physical proof, never grants it.
            let owned = OwnedDedicatedServer {
                child,
                registration: crate::process_inventory::Registration::prepare(
                    "dedicated_server",
                    scene.state_root(),
                    Path::new("/usr/bin/true"),
                    "app-server".to_owned(),
                    None,
                    None,
                    Some(worker.run_id),
                )
                .unwrap(),
                identity: DedicatedServerIdentity {
                    pid,
                    process_group_id: pid,
                    session_id: pid,
                    uid: worker.uid,
                    start_tvsec: 1,
                    start_tvusec: 0,
                    executable_path: PathBuf::from(&executable.resolved_path),
                    executable_device: executable.device,
                    executable_inode: executable.inode,
                    executable_sha256: executable.sha256.clone(),
                },
                socket_path: session.app_server_socket.clone(),
                socket_identity: SocketIdentity {
                    device: 1,
                    inode: 1,
                },
            };
            let build = current_dolgorae_build().unwrap();
            let record = WorkerRuntimeRecord {
                schema_version: 2,
                identity: worker.clone(),
                socket_path: worker_socket_path(worker.uid, &worker.workspace_id, worker.run_id)
                    .unwrap(),
                socket_identity: SocketIdentity {
                    device: 1,
                    inode: 1,
                },
                control_socket_epoch: 1,
                app_server_epoch: Some(1),
                control_recovery_required: false,
                startup_scope: Some(StartupScopeWitness {
                    worker_identity: worker,
                    app_server_epoch: 1,
                    dedicated_server_identity: None,
                    app_server_socket_identity: None,
                    revision: 1,
                    complete: false,
                    children: vec![],
                }),
                dedicated_server_identity: None,
                dolgorae_version: build.version,
                mutation_protocol_version: build.mutation_protocol_version,
                binary_sha256: build.binary_sha256,
            };
            let path =
                runtime_record_path(&runtime_root(scene.state_root()), manifest.run_id).unwrap();
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::set_permissions(path.parent().unwrap(), fs::Permissions::from_mode(0o700)).unwrap();
            let error = QualifiedCallerRuntime::from_owned_server(
                manifest,
                &session,
                &owned,
                record,
                path.clone(),
            )
            .err()
            .expect("absent socket must refuse physical qualification");
            assert!(
                matches!(error, WorkerProtocolError::SocketIdentityMismatch),
                "{error:?}"
            );
            let retained = read_runtime_record(&path, DarwinSystem.current_uid()).unwrap();
            assert_eq!(
                retained
                    .dedicated_server_identity
                    .unwrap()
                    .executable_sha256,
                executable.sha256
            );
            assert!(!retained.startup_scope.unwrap().complete);
        }
    }

    #[test]
    fn primary_completion_reservation_survives_shutdown_and_bounds_admission() {
        let mailbox = SessionMailbox::new(RunFacts {
            run_id: Uuid::now_v7(),
            profile: "default".to_owned(),
        });
        for _ in 0..MAX_PENDING_PRIMARY_TOOLS {
            mailbox.reserve_primary_tool().unwrap();
        }
        assert_eq!(mailbox.reserve_primary_tool().unwrap_err().code, "RUN_BUSY");
        for _ in 1..MAX_PENDING_PRIMARY_TOOLS {
            mailbox.release_primary_tool();
        }
        assert!(mailbox.stop().is_empty());
        mailbox.complete_primary_tool(PrimaryToolCompletion {
            request_id: 7,
            run_generation: 3,
            source_tool_call_id: "call-7".to_owned(),
            result: Ok(serde_json::json!({"operation":"list_specialists_result"})),
        });
        let SessionWork::PrimaryTool(completion) = mailbox.next_work() else {
            panic!("the reserved completion must drain before shutdown");
        };
        assert_eq!(completion.source_tool_call_id, "call-7");
        assert!(matches!(mailbox.next_work(), SessionWork::Stop));
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn prepared_image_identity_detects_content_drift_before_effects() {
        let path =
            std::path::PathBuf::from("/tmp").join(format!("dg-image-admission-{}", Uuid::now_v7()));
        std::fs::write(&path, b"original image bytes").unwrap();
        let mut request = TurnControlRequest {
            write: false,
            normalized_request_sha256: None,
            message: "inspect image".to_owned(),
            idempotency_key: "image-once".to_owned(),
            effort: None,
            images: vec![TurnControlImage {
                detail: ImageDetail::Auto,
                path: path.clone(),
            }],
        };
        let captured = turn_request_with_model("gpt-5", &request, DeliveryMode::Submit).unwrap();
        request.normalized_request_sha256 =
            Some(crate::turn::normalized_request_digest(&captured, "medium").unwrap());
        verify_turn_request_identity(&request, &captured, "medium").unwrap();
        std::fs::write(&path, b"replacement image bytes").unwrap();
        let changed = turn_request_with_model("gpt-5", &request, DeliveryMode::Submit).unwrap();
        assert!(matches!(
            verify_turn_request_identity(&request, &changed, "medium"),
            Err(TurnError::IdempotencyConflict { .. })
        ));
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn prepared_abort_wrapper_preserves_identity_and_accepts_only_direct_turn_requests() {
        let admission_id = Uuid::now_v7();
        let abort = |request| ControlRequestV1::AbortPreparedMutation {
            admission_id,
            request: Box::new(request),
        };
        let expected = identity();
        let mut wrapped = abort(ControlRequestV1::Submit {
            expected: expected.clone(),
            caller: None,
            request: TurnControlRequest {
                write: true,
                normalized_request_sha256: None,
                message: "write after admission".to_owned(),
                idempotency_key: "prepared-only".to_owned(),
                effort: None,
                images: Vec::new(),
            },
        });
        assert!(wrapped.valid_checked_mutation());
        assert!(wrapped.requires_controller());
        assert!(!wrapped.frozen_control_v1());
        assert_eq!(wrapped.expected(), &expected);
        assert_eq!(wrapped.operation_name(), "run.submit");
        let build = ExecutingBuild {
            version: "0.1.2".to_owned(),
            mutation_protocol_version: 1,
            binary_sha256: "11".repeat(32),
        };
        wrapped.declare_caller(build.clone());
        assert_eq!(wrapped.caller(), Some(&build));
        let encoded = serde_json::to_vec(&wrapped).unwrap();
        assert_eq!(
            serde_json::from_slice::<ControlRequestV1>(&encoded).unwrap(),
            wrapped
        );
        assert!(!abort(wrapped).valid_checked_mutation());
        assert!(
            !abort(ControlRequestV1::Interrupt {
                expected,
                caller: None,
            })
            .valid_checked_mutation()
        );
    }

    #[test]
    fn checked_mutations_preserve_identity_and_reject_scope_expansion() {
        let checked = |request| ControlRequestV1::CheckedMutation {
            expected_state_revision: 0,
            request: Box::new(request),
        };
        let expected = identity();
        let mut request = checked(ControlRequestV1::Interrupt {
            expected: expected.clone(),
            caller: None,
        });
        assert!(request.valid_checked_mutation());
        assert!(request.requires_controller());
        assert!(!request.frozen_control_v1());
        assert_eq!(request.expected(), &expected);
        assert_eq!(request.operation_name(), "run.interrupt");
        let build = ExecutingBuild {
            version: "0.1.2".to_owned(),
            mutation_protocol_version: 1,
            binary_sha256: "11".repeat(32),
        };
        request.declare_caller(build.clone());
        assert_eq!(request.caller(), Some(&build));
        let encoded = serde_json::to_vec(&request).unwrap();
        assert_eq!(
            serde_json::from_slice::<ControlRequestV1>(&encoded).unwrap(),
            request
        );
        assert!(!checked(request).valid_checked_mutation());
        assert!(
            !checked(ControlRequestV1::Status {
                expected: identity()
            })
            .valid_checked_mutation()
        );
        assert!(
            !checked(ControlRequestV1::Shutdown {
                expected: identity()
            })
            .valid_checked_mutation()
        );
        assert!(
            !checked(ControlRequestV1::ExternalInterrupt {
                expected: identity(),
                caller: None,
                engagement_id: Uuid::now_v7()
            })
            .valid_checked_mutation()
        );
    }

    #[test]
    fn caller_policy_proof_requires_the_exact_prepared_write_turn() {
        let root = std::env::temp_dir().join(format!("dg-policy-admission-{}", Uuid::now_v7()));
        fs::DirBuilder::new().mode(0o700).create(&root).unwrap();
        fs::DirBuilder::new()
            .mode(0o700)
            .create(root.join("recovery"))
            .unwrap();
        OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o600)
            .open(root.join("audit.jsonl"))
            .unwrap();
        let expected = identity();
        let mut ledger = Ledger::open(&root, expected.run_id).unwrap();
        ledger
            .append_conformance_payload(
                crate::audit::AuditKind::LifecycleTransition,
                &serde_json::json!({"previous":"starting","current":"idle"}),
                1,
            )
            .unwrap();
        let controller = Uuid::now_v7();
        let proof = ControlRequestV1::VerifyCallerPolicy {
            engagement_id: None,
            expected: expected.clone(),
            caller: None,
            operation_id: Uuid::now_v7(),
        };
        for (send, write) in [(true, true), (false, true), (true, false), (false, false)] {
            let request = TurnControlRequest {
                write,
                normalized_request_sha256: None,
                message: "prepared task".to_owned(),
                idempotency_key: format!("{send}-{write}"),
                effort: None,
                images: Vec::new(),
            };
            let turn = if send {
                ControlRequestV1::Send {
                    expected: expected.clone(),
                    caller: None,
                    request,
                    timeout_ms: Some(1000),
                }
            } else {
                ControlRequestV1::Submit {
                    expected: expected.clone(),
                    caller: None,
                    request,
                }
            };
            let head = ledger.head().unwrap().sequence;
            let admission = admit_mutation(&mut ledger, controller, head, &turn).unwrap();
            let before = fs::read(root.join("audit.jsonl")).unwrap();
            let verified =
                validate_mutation_admission(&ledger, admission.admission_id, controller, &proof);
            if write {
                verified.unwrap();
            } else {
                assert_eq!(verified.unwrap_err().code, "RUN_STATE_CONFLICT");
            }
            for (id, owner) in [
                (Uuid::now_v7(), controller),
                (admission.admission_id, Uuid::now_v7()),
            ] {
                assert_eq!(
                    validate_mutation_admission(&ledger, id, owner, &proof)
                        .unwrap_err()
                        .code,
                    "RUN_STATE_CONFLICT"
                );
            }
            assert_eq!(fs::read(root.join("audit.jsonl")).unwrap(), before);
            assert_eq!(
                active_mutation_admission(&ledger)
                    .unwrap()
                    .unwrap()
                    .admission_id,
                admission.admission_id
            );
            let operation = Uuid::now_v7();
            let head = ledger.head().unwrap();
            let source_generation = ledger.projection().unwrap().run_generation.max(1);
            let holder = crate::writer::WriterHolder {
                run_id: expected.run_id,
                profile: "fixture".to_owned(),
                controller_id: controller,
                controller_generation: 1,
                run_generation: source_generation,
                worker_generation: source_generation,
                profile_server_key: "a".repeat(64),
                profile_server_epoch: 1,
                thread_id: Some("original".to_owned()),
                lifecycle: crate::domain::RunLifecycle::Idle,
                active_turn_id: None,
                pending_interaction_count: 0,
                last_event_cursor: None,
            };
            let mut writer = crate::writer::WriterRecord::empty(&expected.workspace_id);
            writer.state = crate::writer::WriterAuthorityState::Reserved;
            writer.transaction_id = Some(operation);
            writer.writer_generation = 1;
            writer.authority_revision = 1;
            writer.holder = Some(holder.clone());
            writer.generation_release = Some(crate::writer::GenerationRelease {
                purpose: crate::writer::GenerationRetirementPurpose::Acquire,
                transaction_id: operation,
                source: holder,
                writer_generation: 1,
                authority_revision: 1,
                source_revision: head.sequence,
                source_ledger_sha256: crate::jcs::sha256_hex(&serde_json::to_vec(&head).unwrap()),
                source_runtime_sha256: "1".repeat(64),
                registration_sha256: "2".repeat(64),
                scope_sha256: None,
                absence_sha256: None,
                reader_proof_sha256: None,
                retired_reader_sha256: None,
                phase: crate::writer::GenerationReleasePhase::Prepared,
                successor: None,
            });
            let command = SessionCommand::PrepareGenerationRetirement {
                transaction_id: operation,
                writer_revision: 1,
                source_revision: head.sequence,
            };
            let records = ledger.durable_records().unwrap();
            assert_eq!(
                retirement_prepares_original_write(
                    &command, &writer, &admission, controller, 1, records
                )
                .unwrap(),
                write
            );
            if write {
                let mut foreign = admission.clone();
                foreign.request_sha256 = "f".repeat(64);
                assert!(
                    !retirement_prepares_original_write(
                        &command, &writer, &foreign, controller, 1, records
                    )
                    .unwrap()
                );
                assert!(
                    !retirement_prepares_original_write(
                        &command,
                        &writer,
                        &admission,
                        Uuid::now_v7(),
                        1,
                        records
                    )
                    .unwrap()
                );
                writer.generation_release.as_mut().unwrap().purpose =
                    crate::writer::GenerationRetirementPurpose::Release;
                assert!(
                    !retirement_prepares_original_write(
                        &command, &writer, &admission, controller, 1, records
                    )
                    .unwrap()
                );
                let owner = writer.generation_release.as_mut().unwrap();
                owner.purpose = crate::writer::GenerationRetirementPurpose::Acquire;
                owner.phase = crate::writer::GenerationReleasePhase::ReaderStarting;
                owner.successor = Some(crate::writer::ReaderReservation {
                    run_generation: source_generation + 1,
                    server_epoch: 2,
                    control_socket_epoch: 2,
                    attempt_started: true,
                });
                ledger.append_required_payload(crate::audit::AuditKind::TurnIntent,
                    &serde_json::json!({"operation_id":operation,"provisional_thread_id":"original"}), source_generation + 1).unwrap();
                ledger
                    .append_required_payload(
                        crate::audit::AuditKind::ThreadBound,
                        &serde_json::json!({"operation_id":operation,"thread_id":"original"}),
                        source_generation + 1,
                    )
                    .unwrap();
                let verification = SessionCommand::VerifyCallerPolicy {
                    operation_id: operation,
                };
                assert!(
                    retirement_prepares_original_write(
                        &verification,
                        &writer,
                        &admission,
                        controller,
                        1,
                        ledger.durable_records().unwrap()
                    )
                    .unwrap()
                );
            }
            validate_mutation_admission(&ledger, admission.admission_id, controller, &turn)
                .unwrap();
            complete_mutation_admission(&mut ledger, admission.admission_id).unwrap();
            if write {
                assert!(
                    retirement_prepares_original_write(
                        &SessionCommand::VerifyCallerPolicy {
                            operation_id: operation
                        },
                        &writer,
                        &admission,
                        controller,
                        1,
                        ledger.durable_records().unwrap(),
                    )
                    .is_err()
                );
            }

            assert_eq!(
                validate_mutation_admission(&ledger, admission.admission_id, controller, &proof)
                    .unwrap_err()
                    .code,
                "RUN_STATE_CONFLICT"
            );
        }
        let wrapped = ControlRequestV1::AdmittedMutation {
            admission_id: Uuid::now_v7(),
            request: Box::new(proof.clone()),
        };
        assert!(wrapped.valid_checked_mutation());
        assert_eq!(
            serde_json::from_slice::<ControlRequestV1>(&serde_json::to_vec(&wrapped).unwrap())
                .unwrap(),
            wrapped
        );
        assert!(
            !ControlRequestV1::BeginPreparedMutation {
                expected_state_revision: 1,
                request: Box::new(proof.clone()),
            }
            .valid_checked_mutation()
        );
        assert!(
            !ControlRequestV1::CheckedMutation {
                expected_state_revision: 1,
                request: Box::new(proof),
            }
            .valid_checked_mutation()
        );
        assert!(
            !ControlRequestV1::AdmittedMutation {
                admission_id: Uuid::now_v7(),
                request: Box::new(wrapped),
            }
            .valid_checked_mutation()
        );
        drop(ledger);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn held_startup_range_rejects_path_mismatch_and_releases_after_spawn_failure() {
        const NAME: &str = "worker::tests::held_startup_range_rejects_path_mismatch_and_releases_after_spawn_failure";
        const ABSENCE_PID: &str = "DOLGORAE_TEST_FAILED_START_ABSENCE_PID";
        if let Ok(pid) = std::env::var(ABSENCE_PID) {
            let pid: u32 = pid.parse().unwrap();
            let deadline = Instant::now() + Duration::from_secs(5);
            let mut empty = 0;
            while empty < 5 {
                let global = DarwinSystem.all_process_identities().unwrap();
                let group = DarwinSystem.process_group_pids(pid).unwrap();
                let absent = matches!(DarwinSystem.bsd_process_identity(pid), Err(error) if error.raw_os_error() == Some(libc::ESRCH));
                if absent && group.is_empty() && !global.iter().any(|p| p.pid == pid) {
                    empty += 1;
                } else {
                    empty = 0;
                }
                assert!(
                    Instant::now() < deadline,
                    "failed-start Child was not reaped"
                );
                if empty < 5 {
                    thread::sleep(Duration::from_millis(100));
                }
            }
            return;
        }

        let state_root =
            std::env::temp_dir().join(format!("dolgorae-held-startup-{}", Uuid::now_v7()));
        fs::create_dir(&state_root).unwrap();
        fs::set_permissions(&state_root, fs::Permissions::from_mode(0o700)).unwrap();
        let runtime = runtime_root(&state_root);
        let uid = DarwinSystem.current_uid();
        prepare_runtime_root(&runtime, uid).unwrap();
        let run_id = Uuid::now_v7();
        let expected_lock_path = startup_lock_path(&runtime, run_id);
        let bootstrap = WorkerBootstrap {
            schema_version: 1,
            workspace_id: "1".repeat(64),
            run_id,
            run_generation: 1,
            boot_uuid: boot_session_uuid(uid).unwrap(),
            executable_sha256: "2".repeat(64),
            executable_path_sha256: "3".repeat(64),
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            control_socket_epoch: 1,
            profile: "default".to_owned(),
            state_root: state_root.clone(),
            ledger_root: state_root.join("runs").join(run_id.to_string()),
            runtime_record_path: runtime_record_path(&runtime, run_id).unwrap(),
            startup_lock_path: expected_lock_path.clone(),
            session: None,
        };
        let bootstrap_path = bootstrap_path(&runtime, run_id);
        write_worker_bootstrap(&bootstrap_path, &bootstrap, uid).unwrap();

        let other_lock_path = startup_lock_path(&runtime, Uuid::now_v7());
        let other_lock = StartupLockFile::open(&other_lock_path, uid).unwrap();
        other_lock
            .hold_startup_range(Duration::from_secs(1))
            .unwrap();
        other_lock
            .write_owner(
                &current_startup_owner(&bootstrap.workspace_id, run_id, bootstrap.run_generation)
                    .unwrap(),
            )
            .unwrap();
        assert!(matches!(
            spawn_hidden_worker_inner(
                &std::env::current_exe().unwrap(),
                &bootstrap_path,
                other_lock
            ),
            Err(WorkerProtocolError::InvalidRuntimeRecord)
        ));
        assert_eq!(
            StartupLockFile::open(&other_lock_path, uid)
                .unwrap()
                .read_owner(0)
                .unwrap(),
            None
        );

        let expected_lock = StartupLockFile::open(&expected_lock_path, uid).unwrap();
        expected_lock
            .hold_startup_range(Duration::from_secs(1))
            .unwrap();
        let owner =
            current_startup_owner(&bootstrap.workspace_id, run_id, bootstrap.run_generation)
                .unwrap();
        assert_eq!(owner.slot, 0);
        assert_eq!(owner.identity.run_id, run_id);
        assert_eq!(owner.identity.pid, std::process::id());
        owner.identity.validate().unwrap();
        expected_lock.write_owner(&owner).unwrap();
        assert!(matches!(
            spawn_hidden_worker_inner(
                Path::new("/definitely/missing/dolgorae-worker"),
                &bootstrap_path,
                expected_lock,
            ),
            Err(WorkerProtocolError::Io)
        ));
        assert_eq!(
            StartupLockFile::open(&expected_lock_path, uid)
                .unwrap()
                .read_owner(0)
                .unwrap(),
            None
        );
        let contender = StartupLockFile::open(&expected_lock_path, uid).unwrap();
        contender.hold_startup_range(Duration::ZERO).unwrap();
        contender.release_startup_range().unwrap();
        fs::create_dir_all(&bootstrap.ledger_root).unwrap();
        let log = bootstrap.ledger_root.join("dedicated-server-1.log");
        OpenOptions::new()
            .create_new(true)
            .write(true)
            .mode(0o600)
            .open(log)
            .unwrap();
        let mut bound_identity = owner.identity.clone();
        bound_identity.executable_sha256 = bootstrap.executable_sha256.clone();
        let bound = WorkerRuntimeRecord {
            schema_version: 1,
            identity: bound_identity,
            socket_path: worker_socket_path(uid, &bootstrap.workspace_id, run_id).unwrap(),
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: None,
            control_recovery_required: false,
            startup_scope: None,
            dedicated_server_identity: None,
            dolgorae_version: bootstrap.dolgorae_version.clone(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: bootstrap.executable_sha256.clone(),
        };
        struct ExitMarker(PathBuf);
        impl Drop for ExitMarker {
            fn drop(&mut self) {
                let _ = fs::write(&self.0, b"exit");
            }
        }
        for after_ready in [false, true] {
            let pid_path = state_root.join(format!("failed-child-{after_ready}.pid"));
            let frame_path = state_root.join(format!("failed-child-{after_ready}.frames"));
            let script = state_root.join(format!("failed-child-{after_ready}.sh"));
            let exit = ExitMarker(state_root.join(format!("failed-child-{after_ready}.exit")));
            let mut frames = Vec::new();
            if after_ready {
                serde_json::to_writer(
                    &mut frames,
                    &StartupHandoff::Bound {
                        record: bound.clone(),
                    },
                )
                .unwrap();
                frames.push(b'\n');
                let mut invalid_ready = bound.clone();
                invalid_ready.socket_identity.inode += 1;
                serde_json::to_writer(
                    &mut frames,
                    &StartupHandoff::Ready {
                        record: invalid_ready,
                    },
                )
                .unwrap();
                frames.push(b'\n');
            }
            fs::write(&frame_path, frames).unwrap();
            fs::write(
                &script,
                format!(
                    "#!/bin/sh\nprintf '%s\\n' \"$$\" > '{}'\n/bin/cat '{}' >&3\n{}while [ ! -f '{}' ]; do /bin/sleep 0.01; done\n",
                    pid_path.display(),
                    frame_path.display(),
                    if after_ready { "" } else { "exec 3>&-\n" },
                    exit.0.display()
                ),
            )
            .unwrap();
            fs::set_permissions(&script, fs::Permissions::from_mode(0o700)).unwrap();
            let lock = StartupLockFile::open(&expected_lock_path, uid).unwrap();
            lock.hold_startup_range(Duration::ZERO).unwrap();
            lock.write_owner(&owner).unwrap();
            let result = spawn_hidden_worker_inner(&script, &bootstrap_path, lock);
            if after_ready {
                assert!(
                    matches!(result, Err(WorkerProtocolError::ProtocolMismatch { .. })),
                    "actual failed-start error: {:?}",
                    result.as_ref().err()
                );
            } else {
                assert!(matches!(result, Err(WorkerProtocolError::MalformedFrame)));
            }
            // Handoff EOF/validation must return while the actual Child is
            // still held by its exit marker. Only then allow its real exit.
            fs::write(&exit.0, b"exit").unwrap();
            let pid: u32 = fs::read_to_string(&pid_path)
                .unwrap()
                .trim()
                .parse()
                .unwrap();
            // A different process verifies complete kernel/group/global absence.
            // The actual parent blocks without any Child/reaper observer call.
            let status = Command::new(std::env::current_exe().unwrap())
                .args(["--exact", NAME, "--test-threads=1"])
                .env(ABSENCE_PID, pid.to_string())
                .stdin(Stdio::null())
                .status()
                .unwrap();
            assert!(status.success());
            assert!(!owned_worker_children().lock().unwrap().contains_key(&pid));
            let contender = StartupLockFile::open(&expected_lock_path, uid).unwrap();
            assert!(contender.read_owner(0).unwrap().is_none());
            contender.hold_startup_range(Duration::ZERO).unwrap();
            contender.release_startup_range().unwrap();
        }
        fs::remove_dir_all(state_root).unwrap();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn display_executable_reuse_revalidates_descriptor_replacement_tampering_and_symlinks() {
        let mounted = Command::new("/sbin/mount").output().is_ok_and(|output| {
            output.status.success()
                && String::from_utf8_lossy(&output.stdout)
                    .lines()
                    .any(|line| line.contains(" on /Volumes/RootKernel ("))
        });
        let name = format!("dolgorae-display-executable-{}", Uuid::now_v7());
        let preferred = Path::new("/Volumes/RootKernel/tmp").join(&name);
        let root = if mounted
            && fs::create_dir_all("/Volumes/RootKernel/tmp").is_ok()
            && fs::DirBuilder::new().mode(0o700).create(&preferred).is_ok()
        {
            preferred
        } else {
            let path = std::env::temp_dir().join(name);
            fs::DirBuilder::new().mode(0o700).create(&path).unwrap();
            path
        };
        let path = root.join("executable");
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o700)
            .open(&path)
            .unwrap();
        file.write_all(b"first executable bytes").unwrap();
        file.sync_all().unwrap();
        drop(file);
        let read = || {
            OpenOptions::new()
                .read(true)
                .custom_flags(libc::O_NOFOLLOW | libc::O_CLOEXEC)
                .open(&path)
                .unwrap()
        };
        let first = display_executable_digest(&path, &mut read()).unwrap();
        let before = display_identity_counters();
        assert_eq!(
            display_executable_digest(&path, &mut read()).unwrap(),
            first
        );
        assert!(display_identity_counters().executable_reuses > before.executable_reuses);
        let mut file = OpenOptions::new().write(true).open(&path).unwrap();
        file.write_all(b"other executable bytes").unwrap();
        file.sync_all().unwrap();
        drop(file);
        let changed = display_executable_digest(&path, &mut read()).unwrap();
        assert_ne!(changed, first);
        fs::rename(&path, root.join("old")).unwrap();
        let mut file = OpenOptions::new()
            .write(true)
            .create_new(true)
            .mode(0o700)
            .open(&path)
            .unwrap();
        file.write_all(b"replaced executable").unwrap();
        file.sync_all().unwrap();
        drop(file);
        assert_ne!(
            display_executable_digest(&path, &mut read()).unwrap(),
            changed
        );
        let mut pinned = read();
        fs::rename(&path, root.join("replaced")).unwrap();
        std::os::unix::fs::symlink(root.join("old"), &path).unwrap();
        assert!(display_executable_digest(&path, &mut pinned).is_err());
        let mut followed = File::open(&path).unwrap();
        assert!(display_executable_digest(&path, &mut followed).is_err());
        fs::remove_file(&path).unwrap();
        fs::rename(root.join("replaced"), &path).unwrap();
        let prior = DisplayExecutableIdentity::read(&read().metadata().unwrap()).unwrap();
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600)).unwrap();
        let stamp = DisplayExecutableIdentity::read(&read().metadata().unwrap()).unwrap();
        assert_eq!(stamp.mode & 0o777, 0o600);
        assert_ne!(stamp, prior);
        assert!(display_executable_digest(&path, &mut read()).is_ok());
        fs::remove_dir_all(root).unwrap();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn four_verdict_identity_matches_current_and_rejects_recorded_reuse() {
        let process = DarwinSystem.current_process().unwrap();
        let sample = DarwinSystem.bsd_process_identity(process.pid).unwrap();
        let executable_path = DarwinSystem
            .realpath(&std::env::current_exe().unwrap())
            .unwrap();
        let metadata = fs::metadata(&executable_path).unwrap();
        let identity = WorkerIdentity {
            workspace_id: "11".repeat(32),
            run_id: Uuid::now_v7(),
            run_generation: 1,
            boot_uuid: Uuid::parse_str(&DarwinSystem.boot_session_uuid().unwrap()).unwrap(),
            pid: process.pid,
            process_group_id: process.process_group_id,
            session_id: sample.session_id,
            uid: process.uid,
            start_tvsec: sample.start_tvsec,
            start_tvusec: sample.start_tvusec,
            executable_path: executable_path.clone(),
            executable_device: metadata.dev(),
            executable_inode: metadata.ino(),
            executable_sha256: file_sha256(&std::env::current_exe().unwrap()).unwrap(),
        };
        let mut record = WorkerRuntimeRecord {
            schema_version: 1,
            socket_path: worker_socket_path(identity.uid, &identity.workspace_id, identity.run_id)
                .unwrap(),
            identity,
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: None,
            control_recovery_required: false,
            startup_scope: None,
            dedicated_server_identity: None,
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: current_dolgorae_build().unwrap().binary_sha256,
        };
        assert_eq!(
            classify_worker_identity_for_display(&record),
            classify_worker_identity(&record)
        );
        assert_eq!(
            classify_worker_identity(&record),
            ProcessIdentityVerdict::Match
        );
        let before = display_identity_counters();
        assert_eq!(
            classify_worker_identity_for_display(&record),
            ProcessIdentityVerdict::Match
        );
        assert!(display_identity_counters().executable_reuses > before.executable_reuses);
        let before = display_identity_counters();
        assert_eq!(
            classify_worker_identity(&record),
            ProcessIdentityVerdict::Match
        );
        assert!(display_identity_counters().authoritative_hashes > before.authoritative_hashes);
        record.identity.start_tvusec = record.identity.start_tvusec.saturating_add(1);
        assert_eq!(
            classify_worker_identity_for_display(&record),
            classify_worker_identity(&record)
        );
        assert_eq!(
            classify_worker_identity(&record),
            ProcessIdentityVerdict::Mismatch
        );
        record.identity.start_tvusec = sample.start_tvusec;
        record.identity.executable_path = PathBuf::from("/missing/dolgorae-worker");
        assert_eq!(
            classify_worker_identity_for_display(&record),
            classify_worker_identity(&record)
        );
        assert_eq!(
            classify_worker_identity(&record),
            ProcessIdentityVerdict::Unverifiable
        );
        record.identity.executable_path = executable_path;
        record.identity.boot_uuid = Uuid::now_v7();
        assert_eq!(
            classify_worker_identity_for_display(&record),
            classify_worker_identity(&record)
        );
        assert_eq!(
            classify_worker_identity(&record),
            ProcessIdentityVerdict::Absent
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn live_exec_invalidates_worker_and_dedicated_identity_without_pid_reuse() {
        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", "printf ready; read ready; exec /bin/sleep 30"])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::null());
        let mut child = DarwinSystem.spawn_detached(&mut command).unwrap();
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let mut ready = [0_u8; 5];
            std::io::Read::read_exact(child.stdout.as_mut().unwrap(), &mut ready).unwrap();
            assert_eq!(&ready, b"ready");
            let executable_path = DarwinSystem.live_process_path(child.id()).unwrap();
            let before = DarwinSystem.bsd_process_identity(child.id()).unwrap();
            let metadata = fs::metadata(&executable_path).unwrap();
            let dedicated = DedicatedServerIdentity {
                pid: before.pid,
                process_group_id: before.process_group_id,
                session_id: before.session_id,
                uid: before.uid,
                start_tvsec: before.start_tvsec,
                start_tvusec: before.start_tvusec,
                executable_device: metadata.dev(),
                executable_inode: metadata.ino(),
                executable_sha256: file_sha256(&executable_path).unwrap(),
                executable_path: executable_path.clone(),
            };
            let identity = WorkerIdentity {
                workspace_id: "11".repeat(32),
                run_id: Uuid::now_v7(),
                run_generation: 1,
                boot_uuid: Uuid::parse_str(&DarwinSystem.boot_session_uuid().unwrap()).unwrap(),
                pid: before.pid,
                process_group_id: before.process_group_id,
                session_id: before.session_id,
                uid: before.uid,
                start_tvsec: before.start_tvsec,
                start_tvusec: before.start_tvusec,
                executable_device: metadata.dev(),
                executable_inode: metadata.ino(),
                executable_sha256: dedicated.executable_sha256.clone(),
                executable_path,
            };
            let record = WorkerRuntimeRecord {
                schema_version: 1,
                socket_path: worker_socket_path(
                    identity.uid,
                    &identity.workspace_id,
                    identity.run_id,
                )
                .unwrap(),
                identity,
                socket_identity: SocketIdentity {
                    device: 1,
                    inode: 1,
                },
                control_socket_epoch: 1,
                app_server_epoch: Some(1),
                control_recovery_required: false,
                startup_scope: None,
                dedicated_server_identity: Some(dedicated.clone()),
                dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
                mutation_protocol_version: WORKER_PROTOCOL_VERSION,
                binary_sha256: "a".repeat(64),
            };
            assert_eq!(
                classify_worker_identity_for_display(&record),
                classify_worker_identity(&record)
            );
            assert_eq!(
                classify_worker_identity(&record),
                ProcessIdentityVerdict::Match
            );
            assert_eq!(
                classify_dedicated_server_identity_for_display(&dedicated),
                classify_dedicated_server_identity(&dedicated)
            );
            assert_eq!(
                classify_dedicated_server_identity(&dedicated),
                ProcessIdentityVerdict::Match
            );
            child.stdin.as_mut().unwrap().write_all(b"go\n").unwrap();
            let sleep_path = DarwinSystem.realpath(Path::new("/bin/sleep")).unwrap();
            let deadline = Instant::now() + Duration::from_secs(3);
            while DarwinSystem.live_process_path(child.id()).as_ref() != Some(&sleep_path) {
                assert!(Instant::now() < deadline);
                thread::sleep(Duration::from_millis(10));
            }
            let after = DarwinSystem.bsd_process_identity(child.id()).unwrap();
            assert_eq!(
                (
                    before.pid,
                    before.start_tvsec,
                    before.start_tvusec,
                    before.process_group_id
                ),
                (
                    after.pid,
                    after.start_tvsec,
                    after.start_tvusec,
                    after.process_group_id
                )
            );
            assert_eq!(
                classify_worker_identity_for_display(&record),
                classify_worker_identity(&record)
            );
            assert_eq!(
                classify_worker_identity(&record),
                ProcessIdentityVerdict::Mismatch
            );
            assert_eq!(
                classify_dedicated_server_identity_for_display(&dedicated),
                classify_dedicated_server_identity(&dedicated)
            );
            assert_eq!(
                classify_dedicated_server_identity(&dedicated),
                ProcessIdentityVerdict::Mismatch
            );
        }));
        let _ = child.kill();
        let _ = child.wait();
        if let Err(panic) = result {
            std::panic::resume_unwind(panic);
        }
    }

    #[test]
    fn process_scope_does_not_trust_effective_uid_changes() {
        let identity = crate::darwin::ProcessCensusEntry {
            pid: 44,
            parent_pid: 43,
            uid: 0,
            process_group_id: 42,
            session_id: 42,
            birth: Some((1, 0)),
            zombie: false,
        };
        let parents = [(44, 43), (43, 42)].into_iter().collect();
        assert!(process_is_in_scope(&identity, 42, 42, 42, &parents));

        let detached = crate::darwin::ProcessCensusEntry {
            process_group_id: 99,
            session_id: 99,
            parent_pid: 1,
            ..identity
        };
        assert!(!process_is_in_scope(
            &detached,
            42,
            42,
            42,
            &[(44, 1)].into_iter().collect()
        ));
    }

    #[test]
    fn startup_child_tracking_rejects_scope_escape_and_pid_reuse() {
        let worker = identity();
        let server = DedicatedServerIdentity {
            pid: worker.pid,
            process_group_id: worker.process_group_id,
            session_id: worker.session_id,
            uid: worker.uid,
            start_tvsec: worker.start_tvsec,
            start_tvusec: worker.start_tvusec,
            executable_path: worker.executable_path,
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256,
        };
        let child = crate::darwin::ProcessCensusEntry {
            pid: 44,
            parent_pid: server.pid,
            uid: server.uid,
            process_group_id: server.process_group_id,
            session_id: server.session_id,
            birth: Some((2, 0)),
            zombie: false,
        };
        let before_window = Instant::now();
        let mut wait = StartupWorkload::new(
            Duration::from_secs(900),
            PathBuf::from("/unused"),
            SocketIdentity {
                device: 1,
                inode: 1,
            },
            server.uid,
        );
        assert!(wait.deadline >= before_window + Duration::from_secs(30));
        assert!(wait.deadline <= Instant::now() + Duration::from_secs(30));
        let before_short = Instant::now();
        let short = StartupWorkload::new(
            Duration::from_secs(1),
            PathBuf::from("/unused"),
            SocketIdentity {
                device: 1,
                inode: 1,
            },
            server.uid,
        );
        assert!(short.deadline >= before_short + Duration::from_secs(1));
        assert!(short.deadline <= Instant::now() + Duration::from_secs(1));
        wait.observe(&child, &server, &mut None).unwrap();
        for (changed, mismatch) in [
            (crate::darwin::ProcessCensusEntry { uid: 0, ..child }, "uid"),
            (
                crate::darwin::ProcessCensusEntry {
                    process_group_id: 99,
                    ..child
                },
                "process_group",
            ),
            (
                crate::darwin::ProcessCensusEntry {
                    session_id: 99,
                    ..child
                },
                "session",
            ),
            (
                crate::darwin::ProcessCensusEntry {
                    birth: None,
                    ..child
                },
                "birth_missing",
            ),
            (
                crate::darwin::ProcessCensusEntry {
                    birth: Some((2, 1)),
                    ..child
                },
                "prior_identity",
            ),
        ] {
            let mut diagnostic = Value::Null;
            assert_eq!(
                wait.observe(&changed, &server, &mut Some(&mut diagnostic)),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(wait.children[&child.pid], child);
            assert_eq!(diagnostic["predicate"], "startup_child_identity");
            let observed = &diagnostic["observation"];
            assert_eq!(observed["pid"], child.pid);
            assert_eq!(observed["prior"], scope_observation(&child));
            assert_eq!(observed["expected_server"]["pid"], server.pid);
            assert_eq!(observed["expected_server"]["uid"], server.uid);
            assert_eq!(
                observed["expected_server"]["process_group_id"],
                server.process_group_id
            );
            assert_eq!(observed["expected_server"]["session_id"], server.session_id);
            assert_eq!(observed["mismatches"][mismatch], true);
        }
    }

    #[test]
    fn startup_ancestry_preserves_identity_while_children_exit() {
        let leader = crate::darwin::ProcessCensusEntry {
            pid: 100,
            parent_pid: 99,
            uid: 501,
            process_group_id: 100,
            session_id: 100,
            birth: Some((10, 1)),
            zombie: false,
        };
        let parent = crate::darwin::ProcessCensusEntry {
            pid: 101,
            parent_pid: 100,
            birth: Some((10, 2)),
            ..leader
        };
        let leaf = crate::darwin::ProcessCensusEntry {
            pid: 102,
            parent_pid: 101,
            birth: Some((10, 3)),
            ..leader
        };
        let first = [leaf, parent, leader];
        let mut second = first;
        second[0].zombie = true;
        second[1].zombie = true;
        let worker = identity();
        let server = DedicatedServerIdentity {
            pid: leader.pid,
            process_group_id: leader.process_group_id,
            session_id: leader.session_id,
            uid: leader.uid,
            start_tvsec: 10,
            start_tvusec: 1,
            executable_path: worker.executable_path,
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256,
        };
        assert_eq!(
            startup_ancestry(&second, &leaf, &server),
            Some(second.to_vec())
        );
        assert!(startup_ancestries_match(&first, &second));
        assert!(startup_ancestries_match(&second, &first));
        assert!(!startup_ancestries_match(&first, &second[..2]));

        let stale_leaf = [leaf, leader];
        assert!(startup_ancestry(&stale_leaf, &leaf, &server).is_none());
        let exited = |_| Err(std::io::Error::from_raw_os_error(libc::ESRCH));
        let mut probed = Vec::new();
        assert!(startup_child_exited(&first, &stale_leaf, |pid| {
            probed.push(pid);
            exited(pid)
        }));
        assert_eq!(probed, [leaf.pid, parent.pid]);
        assert!(startup_child_exited(&first, &[parent, leader], exited));
        assert!(!startup_child_exited(&first, &[leaf], exited));

        let inaccessible = |_| Err(std::io::Error::from_raw_os_error(libc::EPERM));
        assert!(!startup_child_exited(&first, &stale_leaf, inaccessible));
        let live = crate::darwin::BsdProcessIdentity {
            pid: leaf.pid,
            parent_pid: leaf.parent_pid,
            uid: leaf.uid,
            process_group_id: leaf.process_group_id,
            session_id: leaf.session_id,
            start_tvsec: 10,
            start_tvusec: 3,
            zombie: true,
        };
        assert!(!startup_child_exited(&first, &stale_leaf, |_| Ok(live)));
        assert!(!startup_child_exited(&first, &stale_leaf, |pid| {
            if pid == leaf.pid {
                exited(pid)
            } else {
                inaccessible(pid)
            }
        }));
        for changed in [
            crate::darwin::ProcessCensusEntry {
                birth: Some((20, 1)),
                ..leaf
            },
            crate::darwin::ProcessCensusEntry {
                parent_pid: 1,
                ..leaf
            },
        ] {
            assert!(!startup_child_exited(&first, &[changed, leader], exited));
        }

        for ancestor in 0..first.len() {
            for changed in [
                crate::darwin::ProcessCensusEntry {
                    pid: first[ancestor].pid + 1,
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    parent_pid: first[ancestor].parent_pid + 1,
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    uid: first[ancestor].uid + 1,
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    process_group_id: 200,
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    session_id: 200,
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    birth: Some((11, 1)),
                    ..first[ancestor]
                },
                crate::darwin::ProcessCensusEntry {
                    birth: None,
                    ..first[ancestor]
                },
            ] {
                let mut drifted = second;
                drifted[ancestor] = changed;
                assert!(!startup_ancestries_match(&first, &drifted));
                if ancestor == 0 {
                    assert!(startup_ancestry(&drifted, &leaf, &server).is_none());
                }
            }
        }
    }

    #[test]
    fn startup_ancestry_and_observe_owned_handle_toctou_and_fail_closed() {
        let leader = crate::darwin::ProcessCensusEntry {
            pid: 51582,
            parent_pid: 51500,
            uid: 501,
            process_group_id: 51582,
            session_id: 51582,
            birth: Some((100, 1)),
            zombie: false,
        };
        let parent = crate::darwin::ProcessCensusEntry {
            pid: 55412,
            parent_pid: leader.pid,
            birth: Some((100, 2)),
            ..leader
        };
        let child = crate::darwin::ProcessCensusEntry {
            pid: 55439,
            parent_pid: parent.pid,
            birth: Some((100, 3)),
            ..leader
        };
        let direct_child = crate::darwin::ProcessCensusEntry {
            pid: 55440,
            parent_pid: leader.pid,
            birth: Some((100, 4)),
            ..leader
        };
        let worker = identity();
        let server = DedicatedServerIdentity {
            pid: leader.pid,
            process_group_id: leader.process_group_id,
            session_id: leader.session_id,
            uid: leader.uid,
            start_tvsec: 100,
            start_tvusec: 1,
            executable_path: worker.executable_path,
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256,
        };
        let new_wait = || {
            StartupWorkload::new(
                Duration::from_secs(10),
                PathBuf::from("/unused"),
                SocketIdentity {
                    device: 1,
                    inode: 1,
                },
                server.uid,
            )
        };
        let esrch = || Err(std::io::Error::from_raw_os_error(libc::ESRCH));
        let eperm = || Err(std::io::Error::from_raw_os_error(libc::EPERM));

        // Positive 1: short-lived direct child exits (ESRCH) between lookup and fresh census.
        let mut wait = new_wait();
        wait.dirty_sample = false;
        let fresh = vec![leader];
        wait.observe_owned_with(
            &direct_child,
            &server,
            &fresh,
            "dedicated_membership",
            &mut None,
            || panic!("second census should not be taken for exited child"),
            |pid| {
                assert_eq!(pid, direct_child.pid);
                esrch()
            },
        )
        .unwrap();
        assert!(wait.dirty_sample);
        assert!(wait.children.is_empty());

        // Positive 2: short-lived grandchild exits (ESRCH) whose verified self.children parent
        // also exited (ESRCH) before fresh census.
        let mut wait = new_wait();
        wait.children.insert(parent.pid, parent);
        wait.dirty_sample = false;
        wait.observe_owned_with(
            &child,
            &server,
            &[leader],
            "dedicated_membership",
            &mut None,
            || panic!("second census should not be taken for exited grandchild"),
            |pid| {
                assert!(pid == child.pid || pid == parent.pid);
                esrch()
            },
        )
        .unwrap();
        assert!(wait.dirty_sample);
        assert!(!wait.children.contains_key(&child.pid));

        // Positive 3: verified self.children parent exits (ESRCH) while live grandchild
        // is observed in both census and second_census -> ancestry succeeds & child recorded.
        let mut wait = new_wait();
        wait.children.insert(parent.pid, parent);
        let live_fresh = vec![child, leader];
        wait.observe_owned_with(
            &child,
            &server,
            &live_fresh,
            "dedicated_membership",
            &mut None,
            || Ok(live_fresh.clone()),
            |pid| {
                assert_eq!(pid, parent.pid);
                esrch()
            },
        )
        .unwrap();
        assert!(wait.dirty_sample);
        assert_eq!(wait.children.get(&child.pid), Some(&child));

        // Positive 4: startup_child_exited accepts exact-matching zombie child when
        // intermediate parent exited (ESRCH), while rejecting non-zombie live child.
        let first = [child, parent, leader];
        let mut zombie_child_entry = child;
        zombie_child_entry.zombie = true;
        let zombie_bsd = crate::darwin::BsdProcessIdentity {
            pid: child.pid,
            parent_pid: child.parent_pid,
            uid: child.uid,
            process_group_id: child.process_group_id,
            session_id: child.session_id,
            start_tvsec: 100,
            start_tvusec: 3,
            zombie: true,
        };
        assert!(startup_child_exited(
            &first,
            &[zombie_child_entry, leader],
            |pid| if pid == child.pid {
                Ok(zombie_bsd)
            } else {
                esrch()
            }
        ));
        let non_zombie_bsd = crate::darwin::BsdProcessIdentity {
            zombie: false,
            ..zombie_bsd
        };
        assert!(!startup_child_exited(&first, &[child, leader], |pid| {
            if pid == child.pid {
                Ok(non_zombie_bsd)
            } else {
                esrch()
            }
        }));

        // Negative 1 (security): unowned parent's exited child -> Err(InvalidIdentity) startup_child_ancestry.
        let mut wait = new_wait();
        let mut details = Value::Null;
        assert_eq!(
            wait.observe_owned_with(
                &child,
                &server,
                &[leader],
                "dedicated_membership",
                &mut Some(&mut details),
                || Ok(vec![leader]),
                |_| esrch(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        assert_eq!(details["predicate"], "startup_child_ancestry");

        // Negative 2 (security): EPERM lookup on exited child OR on exited self.children parent -> Err(InvalidIdentity).
        let mut wait = new_wait();
        let mut details = Value::Null;
        assert_eq!(
            wait.observe_owned_with(
                &direct_child,
                &server,
                &[leader],
                "dedicated_membership",
                &mut Some(&mut details),
                || Ok(vec![leader]),
                |_| eperm(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        assert_eq!(details["predicate"], "startup_child_ancestry");

        let mut wait = new_wait();
        wait.children.insert(parent.pid, parent);
        assert_eq!(
            wait.observe_owned_with(
                &child,
                &server,
                &live_fresh,
                "dedicated_membership",
                &mut None,
                || Ok(live_fresh.clone()),
                |_| eperm(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        // Negative 3 (security): recycled PID (birth mismatch / live process returned for
        // exited self.children parent, or non-monotonic birth order) -> Err(InvalidIdentity).
        let mut wait = new_wait();
        wait.children.insert(parent.pid, parent);
        let recycled_parent = crate::darwin::BsdProcessIdentity {
            pid: parent.pid,
            parent_pid: 1,
            uid: server.uid,
            process_group_id: parent.pid,
            session_id: parent.pid,
            start_tvsec: 200,
            start_tvusec: 0,
            zombie: false,
        };
        assert_eq!(
            wait.observe_owned_with(
                &child,
                &server,
                &live_fresh,
                "dedicated_membership",
                &mut None,
                || Ok(live_fresh.clone()),
                |_| Ok(recycled_parent),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        let mut wait = new_wait();
        let newer_parent = crate::darwin::ProcessCensusEntry {
            birth: Some((100, 9)),
            ..parent
        };
        wait.children.insert(parent.pid, newer_parent);
        assert_eq!(
            wait.observe_owned_with(
                &child,
                &server,
                &live_fresh,
                "dedicated_membership",
                &mut None,
                || Ok(live_fresh.clone()),
                |_| esrch(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        // Negative 4 (security): server missing or mismatched in census -> Err(InvalidIdentity).
        let mut wait = new_wait();
        wait.children.insert(parent.pid, parent);
        assert_eq!(
            wait.observe_owned_with(
                &direct_child,
                &server,
                &[],
                "dedicated_membership",
                &mut None,
                || Ok(vec![]),
                |_| esrch(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        let mismatched_leader = crate::darwin::ProcessCensusEntry {
            birth: Some((999, 1)),
            ..leader
        };
        assert_eq!(
            wait.observe_owned_with(
                &child,
                &server,
                &[child, mismatched_leader],
                "dedicated_membership",
                &mut None,
                || Ok(vec![child, mismatched_leader]),
                |_| esrch(),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
    }

    #[test]
    fn tracked_child_pid_reuse_is_absent_while_same_birth_drift_fails_closed() {
        let child = crate::darwin::ProcessCensusEntry {
            pid: 4000,
            parent_pid: 1000,
            uid: 501,
            process_group_id: 1000,
            session_id: 1000,
            birth: Some((50, 10)),
            zombie: false,
        };
        let exact_bsd = crate::darwin::BsdProcessIdentity {
            pid: child.pid,
            parent_pid: child.parent_pid,
            uid: child.uid,
            process_group_id: child.process_group_id,
            session_id: child.session_id,
            start_tvsec: 50,
            start_tvusec: 10,
            zombie: false,
        };

        assert_eq!(
            classify_tracked_child_identity(
                &child,
                &Err(std::io::Error::from_raw_os_error(libc::ESRCH)),
            ),
            TrackedChildStatus::Absent
        );
        assert_eq!(
            classify_tracked_child_identity(&child, &Ok(exact_bsd)),
            TrackedChildStatus::LiveMatch
        );

        // PID recycled by a different process (different birth timestamp).
        let recycled_birth = crate::darwin::BsdProcessIdentity {
            start_tvsec: 51,
            start_tvusec: 0,
            ..exact_bsd
        };
        assert_eq!(
            classify_tracked_child_identity(&child, &Ok(recycled_birth)),
            TrackedChildStatus::Absent
        );

        // PID recycled by a different UID proven by Ok(current).
        let recycled_uid = crate::darwin::BsdProcessIdentity {
            uid: 0,
            process_group_id: 4000,
            session_id: 4000,
            ..exact_bsd
        };
        assert_eq!(
            classify_tracked_child_identity(&child, &Ok(recycled_uid)),
            TrackedChildStatus::Absent
        );

        // Negative (F-3): EPERM MUST ALWAYS fail closed (IdentityDrift), never Absent.
        assert_eq!(
            classify_tracked_child_identity(
                &child,
                &Err(std::io::Error::from_raw_os_error(libc::EPERM)),
            ),
            TrackedChildStatus::IdentityDrift
        );
        let no_birth_child = crate::darwin::ProcessCensusEntry {
            birth: None,
            ..child
        };
        assert_eq!(
            classify_tracked_child_identity(
                &no_birth_child,
                &Err(std::io::Error::from_raw_os_error(libc::EPERM)),
            ),
            TrackedChildStatus::IdentityDrift
        );

        // Negative: same (uid, birth) drifting pgid or sid must fail closed.
        let drifted_pgid = crate::darwin::BsdProcessIdentity {
            process_group_id: 9999,
            ..exact_bsd
        };
        assert_eq!(
            classify_tracked_child_identity(&child, &Ok(drifted_pgid)),
            TrackedChildStatus::IdentityDrift
        );
        let drifted_sid = crate::darwin::BsdProcessIdentity {
            session_id: 9999,
            ..exact_bsd
        };
        assert_eq!(
            classify_tracked_child_identity(&child, &Ok(drifted_sid)),
            TrackedChildStatus::IdentityDrift
        );

        // StartupWorkload::observe_owned_with: dead prior child's PID reused by a new
        // verified owned child succeeds; live same-birth pgid drift fails closed.
        let worker = identity();
        let leader = crate::darwin::ProcessCensusEntry {
            pid: 1000,
            parent_pid: 999,
            uid: 501,
            process_group_id: 1000,
            session_id: 1000,
            birth: Some((40, 1)),
            zombie: false,
        };
        let server = DedicatedServerIdentity {
            pid: leader.pid,
            process_group_id: leader.process_group_id,
            session_id: leader.session_id,
            uid: leader.uid,
            start_tvsec: 40,
            start_tvusec: 1,
            executable_path: worker.executable_path,
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256,
        };
        let mut wait = StartupWorkload::new(
            Duration::from_secs(10),
            PathBuf::from("/unused"),
            SocketIdentity {
                device: 1,
                inode: 1,
            },
            server.uid,
        );
        wait.children.insert(child.pid, child);

        // Same-birth pgid drift -> rejected.
        let drifted_child = crate::darwin::ProcessCensusEntry {
            process_group_id: 9999,
            ..child
        };
        assert_eq!(
            wait.observe_owned_with(
                &drifted_child,
                &server,
                &[drifted_child, leader],
                "recorded_scope",
                &mut None,
                || Ok(vec![drifted_child, leader]),
                |_| Ok(drifted_pgid),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        // Spoofed different birth while prior is still live in kernel -> rejected.
        let reused_child = crate::darwin::ProcessCensusEntry {
            birth: Some((55, 1)),
            ..child
        };
        assert_eq!(
            wait.observe_owned_with(
                &reused_child,
                &server,
                &[reused_child, leader],
                "recorded_scope",
                &mut None,
                || Ok(vec![reused_child, leader]),
                |_| Ok(exact_bsd),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        // Prior is genuinely absent (kernel shows new birth) and new child descends from server -> accepted & replaced.
        let new_bsd = crate::darwin::BsdProcessIdentity {
            start_tvsec: 55,
            start_tvusec: 1,
            ..exact_bsd
        };
        wait.observe_owned_with(
            &reused_child,
            &server,
            &[reused_child, leader],
            "recorded_scope",
            &mut None,
            || Ok(vec![reused_child, leader]),
            |_| Ok(new_bsd),
        )
        .unwrap();
        assert_eq!(wait.children.get(&child.pid), Some(&reused_child));
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn stop_force_delete_runtime_handles_absent_worker_and_kills_owned_child_group() {
        let root = std::env::temp_dir().join(format!("dolgorae-force-stop-{}", Uuid::now_v7()));
        fs::create_dir_all(&root).unwrap();
        let child_pid_file = root.join("child.pid");
        let mut command = Command::new("/bin/sh");
        command
            .args([
                "-c",
                &format!(
                    "/bin/sleep 60 & echo $! > \"{}\"; wait",
                    child_pid_file.display()
                ),
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut leader = DarwinSystem.spawn_detached(&mut command).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        let child_pid: u32 = loop {
            if let Ok(text) = fs::read_to_string(&child_pid_file)
                && let Ok(pid) = text.trim().parse::<u32>()
            {
                break pid;
            }
            assert!(Instant::now() < deadline, "child pid file not written");
            thread::sleep(Duration::from_millis(10));
        };
        let bsd = DarwinSystem.bsd_process_identity(leader.id()).unwrap();
        let path = DarwinSystem.live_process_path(leader.id()).unwrap();
        let metadata = fs::metadata(&path).unwrap();
        let boot_uuid = Uuid::parse_str(&DarwinSystem.boot_session_uuid().unwrap()).unwrap();
        let run_id = Uuid::now_v7();
        let worker_id = WorkerIdentity {
            workspace_id: "11".repeat(32),
            run_id,
            run_generation: 1,
            boot_uuid,
            pid: bsd.pid,
            process_group_id: bsd.process_group_id,
            session_id: bsd.session_id,
            uid: bsd.uid,
            start_tvsec: bsd.start_tvsec,
            start_tvusec: bsd.start_tvusec,
            executable_path: path.clone(),
            executable_device: metadata.dev(),
            executable_inode: metadata.ino(),
            executable_sha256: file_sha256(&path).unwrap(),
        };
        let server_child_pid_file = root.join("server-child.pid");
        let mut server_command = Command::new("/bin/sh");
        server_command
            .args([
                "-c",
                &format!(
                    "/bin/sleep 60 & echo $! > \"{}\"; wait",
                    server_child_pid_file.display()
                ),
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut dedicated_proc = DarwinSystem.spawn_detached(&mut server_command).unwrap();
        let server_child_pid: u32 = loop {
            if let Ok(text) = fs::read_to_string(&server_child_pid_file)
                && let Ok(pid) = text.trim().parse::<u32>()
            {
                break pid;
            }
            assert!(
                Instant::now() < deadline,
                "server child pid file not written"
            );
            thread::sleep(Duration::from_millis(10));
        };
        let server_bsd = DarwinSystem
            .bsd_process_identity(dedicated_proc.id())
            .unwrap();
        let server_path = DarwinSystem.live_process_path(dedicated_proc.id()).unwrap();
        let server_meta = fs::metadata(&server_path).unwrap();
        let dedicated = DedicatedServerIdentity {
            pid: server_bsd.pid,
            process_group_id: server_bsd.process_group_id,
            session_id: server_bsd.session_id,
            uid: server_bsd.uid,
            start_tvsec: server_bsd.start_tvsec,
            start_tvusec: server_bsd.start_tvusec,
            executable_path: server_path.clone(),
            executable_device: server_meta.dev(),
            executable_inode: server_meta.ino(),
            executable_sha256: file_sha256(&server_path).unwrap(),
        };
        let mut scope = StartupScopeWitness::pending(worker_id.clone(), 1);
        scope.dedicated_server_identity = Some(dedicated.clone());
        scope.app_server_socket_identity = Some(SocketIdentity {
            device: 1,
            inode: 2,
        });
        scope.complete = true;
        let record = WorkerRuntimeRecord {
            schema_version: 2,
            socket_path: worker_socket_path(
                worker_id.uid,
                &worker_id.workspace_id,
                worker_id.run_id,
            )
            .unwrap(),
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: Some(1),
            control_recovery_required: false,
            startup_scope: Some(scope),
            dedicated_server_identity: Some(dedicated),
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: worker_id.executable_sha256.clone(),
            identity: worker_id,
        };
        // Pre-check rejects incomplete startup scope.
        let mut incomplete = record.clone();
        incomplete.startup_scope.as_mut().unwrap().complete = false;
        assert_eq!(
            can_stop_force_delete_runtime(&incomplete),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        // Pre-check accepts verified live worker + dedicated server with active child groups.
        can_stop_force_delete_runtime(&record).unwrap();

        // Spawn reaper threads so detached children don't linger as zombies of this test process.
        let reaper = thread::spawn(move || {
            let _ = leader.wait();
        });
        let server_reaper = thread::spawn(move || {
            let _ = dedicated_proc.wait();
        });
        let mut details = Value::Null;
        stop_force_delete_runtime_observed(&record, Some(&mut details)).unwrap_or_else(|error| {
            panic!("stop_force_delete_runtime failed: {error:?}: {details}")
        });
        reaper.join().unwrap();
        server_reaper.join().unwrap();

        // Worker child and dedicated server child must both now be kernel-absent.
        for pid in [child_pid, server_child_pid] {
            assert_eq!(
                DarwinSystem
                    .bsd_process_identity(pid)
                    .err()
                    .and_then(|e| e.raw_os_error()),
                Some(libc::ESRCH)
            );
        }
        // Re-running stop_force_delete_runtime on an already-Absent worker succeeds cleanly.
        let mut details = Value::Null;
        stop_force_delete_runtime_observed(&record, Some(&mut details)).unwrap_or_else(|error| {
            panic!("stop_force_delete_runtime failed: {error:?}: {details}")
        });
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn force_delete_target_planner_never_targets_recycled_same_uid_bystanders_or_groups() {
        let mut worker = identity();
        worker.pid = 100;
        worker.process_group_id = 100;
        worker.session_id = 100;
        worker.start_tvsec = 10;
        worker.start_tvusec = 1;
        let uid = worker.uid;
        let server = DedicatedServerIdentity {
            pid: 200,
            process_group_id: 200,
            session_id: 200,
            uid,
            start_tvsec: 10,
            start_tvusec: 2,
            executable_path: worker.executable_path.clone(),
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256.clone(),
        };
        let server_entry = crate::darwin::ProcessCensusEntry {
            pid: 200,
            parent_pid: 100,
            uid,
            process_group_id: 200,
            session_id: 200,
            birth: Some((10, 2)),
            zombie: false,
        };
        let group_leader_child = crate::darwin::ProcessCensusEntry {
            pid: 300,
            parent_pid: 200,
            uid,
            process_group_id: 300,
            session_id: 200,
            birth: Some((10, 3)),
            zombie: false,
        };
        let sibling_in_child_group = crate::darwin::ProcessCensusEntry {
            pid: 301,
            parent_pid: 300,
            uid,
            process_group_id: 300,
            session_id: 200,
            birth: Some((10, 4)),
            zombie: false,
        };
        let child_in_server_group = crate::darwin::ProcessCensusEntry {
            pid: 302,
            parent_pid: 200,
            uid,
            process_group_id: 200,
            session_id: 200,
            birth: Some((10, 5)),
            zombie: false,
        };
        let mut scope = StartupScopeWitness::pending(worker.clone(), 1);
        scope.dedicated_server_identity = Some(server.clone());
        scope.app_server_socket_identity = Some(SocketIdentity {
            device: 1,
            inode: 2,
        });
        scope.complete = true;
        scope.children = vec![
            StartupOwnedChild {
                identity: group_leader_child,
                ancestry: vec![group_leader_child, server_entry],
            },
            StartupOwnedChild {
                identity: sibling_in_child_group,
                ancestry: vec![sibling_in_child_group, group_leader_child, server_entry],
            },
            StartupOwnedChild {
                identity: child_in_server_group,
                ancestry: vec![child_in_server_group, server_entry],
            },
        ];
        let record = WorkerRuntimeRecord {
            schema_version: 2,
            socket_path: worker_socket_path(worker.uid, &worker.workspace_id, worker.run_id)
                .unwrap(),
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: Some(1),
            control_recovery_required: false,
            startup_scope: Some(scope),
            dedicated_server_identity: Some(server),
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: worker.executable_sha256.clone(),
            identity: worker,
        };

        // Trigger 1: server absent, tracked child shared server.pgid=200, unrelated U recycled PID 200
        // -> tracked child MUST NOT re-insert pgid 200, and U MUST NOT be targeted!
        let recycled_server_u = crate::darwin::ProcessCensusEntry {
            pid: 200,
            parent_pid: 1,
            uid,
            process_group_id: 200,
            session_id: 200,
            birth: Some((99, 1)),
            zombie: false,
        };
        let planned =
            plan_force_delete_owned_targets(&record, false, false, &[recycled_server_u], &mut None)
                .unwrap();
        assert!(planned.groups.is_empty());
        assert!(planned.processes.is_empty());

        // Trigger 2: group-leader child C1 (pid 300, pgid 300) exited and unrelated U recycled PID 300
        // while sibling C2 shared pgid 300 -> pgid 300 MUST NOT be targeted, and U/U2 MUST NOT be targeted!
        let recycled_child_u = crate::darwin::ProcessCensusEntry {
            pid: 300,
            parent_pid: 1,
            uid,
            process_group_id: 300,
            session_id: 300,
            birth: Some((99, 2)),
            zombie: false,
        };
        let recycled_child_u2 = crate::darwin::ProcessCensusEntry {
            pid: 400,
            parent_pid: 300,
            uid,
            process_group_id: 300,
            session_id: 300,
            birth: Some((99, 3)),
            zombie: false,
        };
        let planned = plan_force_delete_owned_targets(
            &record,
            false,
            false,
            &[recycled_child_u, recycled_child_u2, child_in_server_group],
            &mut None,
        )
        .unwrap();
        assert!(planned.groups.is_empty());
        assert_eq!(planned.processes, vec![child_in_server_group]);

        // Trigger 3: recycled leader U spawned U2 (pid 400, pgid 300, sid 300) and exited!
        let orphan_u2 = crate::darwin::ProcessCensusEntry {
            pid: 400,
            parent_pid: 1,
            uid,
            process_group_id: 300,
            session_id: 300,
            birth: Some((99, 3)),
            zombie: false,
        };
        let planned =
            plan_force_delete_owned_targets(&record, false, false, &[orphan_u2], &mut None)
                .unwrap();
        assert!(planned.groups.is_empty());
        assert!(planned.processes.is_empty());

        // Positive: verified live server + verified live group-leader child DO authorize their groups & descendants.
        let grandchild = crate::darwin::ProcessCensusEntry {
            pid: 350,
            parent_pid: 300,
            uid,
            process_group_id: 350,
            session_id: 200,
            birth: Some((10, 8)),
            zombie: false,
        };
        let planned = plan_force_delete_owned_targets(
            &record,
            false,
            true,
            &[server_entry, group_leader_child, grandchild],
            &mut None,
        )
        .unwrap();
        assert!(planned.groups.contains(&200));
        assert!(planned.groups.contains(&300));
        assert_eq!(planned.processes.len(), 3);

        // Private diagnostic log cap (F-4): refuse appending once >= 1 MiB.
        let cap_root = std::env::temp_dir().join(format!("dolgorae-diag-cap-{}", Uuid::now_v7()));
        fs::create_dir_all(&cap_root).unwrap();
        let log_path = cap_root.join("dedicated-server-1.log");
        fs::write(
            &log_path,
            vec![b'x'; MAX_PRIVATE_DIAGNOSTIC_LOG_BYTES as usize],
        )
        .unwrap();
        fs::set_permissions(&log_path, fs::Permissions::from_mode(0o600)).unwrap();
        append_private_diagnostic(&log_path, &serde_json::json!({"ignored": true}));
        assert_eq!(
            fs::metadata(&log_path).unwrap().len(),
            MAX_PRIVATE_DIAGNOSTIC_LOG_BYTES
        );
        fs::remove_dir_all(cap_root).unwrap();
    }

    #[test]
    fn startup_membership_reconciliation_discards_races_and_preserves_identity_guards() {
        let worker = identity();
        let server = DedicatedServerIdentity {
            pid: worker.pid,
            process_group_id: worker.process_group_id,
            session_id: worker.session_id,
            uid: worker.uid,
            start_tvsec: worker.start_tvsec,
            start_tvusec: worker.start_tvusec,
            executable_path: worker.executable_path,
            executable_device: worker.executable_device,
            executable_inode: worker.executable_inode,
            executable_sha256: worker.executable_sha256,
        };
        let child = crate::darwin::ProcessCensusEntry {
            pid: 44,
            parent_pid: server.pid,
            uid: server.uid,
            process_group_id: server.process_group_id,
            session_id: server.session_id,
            birth: Some((2, 0)),
            zombie: false,
        };
        let current = crate::darwin::BsdProcessIdentity {
            pid: child.pid,
            parent_pid: child.parent_pid,
            uid: child.uid,
            process_group_id: child.process_group_id,
            session_id: child.session_id,
            start_tvsec: 2,
            start_tvusec: 0,
            zombie: false,
        };
        let new_wait = || {
            StartupWorkload::new(
                Duration::from_secs(10),
                PathBuf::from("/unused"),
                SocketIdentity {
                    device: 1,
                    inode: 1,
                },
                server.uid,
            )
        };
        let leader = [server.pid];
        let with_child = [server.pid, child.pid];

        let mut wait = new_wait();
        let deadline = wait.deadline;
        wait.reconcile_membership(&server, &with_child, &leader, &[], &mut None, |_| {
            Err(std::io::Error::from_raw_os_error(libc::ESRCH))
        })
        .unwrap();
        assert!(wait.dirty_sample);
        assert!(wait.children.is_empty());
        assert_eq!(wait.deadline, deadline);

        let mut wait = new_wait();
        wait.reconcile_membership(&server, &with_child, &leader, &[], &mut None, |_| {
            Ok(current)
        })
        .unwrap();
        assert!(wait.dirty_sample);
        assert_eq!(wait.children[&child.pid], child);

        let mut wait = new_wait();
        wait.reconcile_membership(&server, &leader, &with_child, &[child], &mut None, |_| {
            Err(std::io::Error::from_raw_os_error(libc::ESRCH))
        })
        .unwrap();
        assert!(wait.dirty_sample);
        assert_eq!(wait.children[&child.pid], child);

        for changed in [
            crate::darwin::BsdProcessIdentity { pid: 45, ..current },
            crate::darwin::BsdProcessIdentity { uid: 0, ..current },
            crate::darwin::BsdProcessIdentity {
                process_group_id: 99,
                ..current
            },
            crate::darwin::BsdProcessIdentity {
                session_id: 99,
                ..current
            },
        ] {
            assert_eq!(
                new_wait().reconcile_membership(
                    &server,
                    &with_child,
                    &leader,
                    &[],
                    &mut None,
                    |_| Ok(changed),
                ),
                Err(WorkerProtocolError::InvalidIdentity)
            );
        }
        for code in [libc::EPERM, libc::EACCES, libc::EIO] {
            assert_eq!(
                new_wait().reconcile_membership(
                    &server,
                    &with_child,
                    &leader,
                    &[],
                    &mut None,
                    |_| Err(std::io::Error::from_raw_os_error(code)),
                ),
                Err(WorkerProtocolError::InvalidIdentity)
            );
        }
        assert_eq!(
            new_wait().reconcile_membership(
                &server,
                &with_child,
                &leader,
                &[],
                &mut None,
                |_| Err(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "short identity"
                )),
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        assert_eq!(
            new_wait().reconcile_membership(&server, &leader, &[], &[], &mut None, |_| panic!(
                "leader membership drift must refuse before lookup"
            ),),
            Err(WorkerProtocolError::InvalidIdentity)
        );

        for changed in [
            crate::darwin::ProcessCensusEntry { uid: 0, ..child },
            crate::darwin::ProcessCensusEntry {
                process_group_id: 99,
                ..child
            },
            crate::darwin::ProcessCensusEntry {
                session_id: 99,
                ..child
            },
            crate::darwin::ProcessCensusEntry {
                birth: None,
                ..child
            },
        ] {
            assert_eq!(
                new_wait().reconcile_membership(
                    &server,
                    &leader,
                    &with_child,
                    &[changed],
                    &mut None,
                    |_| panic!("typed identity violations must refuse before lookup"),
                ),
                Err(WorkerProtocolError::InvalidIdentity)
            );
        }
        let mut wait = new_wait();
        wait.observe(&child, &server, &mut None).unwrap();
        assert_eq!(
            wait.reconcile_membership(&server, &with_child, &leader, &[], &mut None, |_| Ok(
                crate::darwin::BsdProcessIdentity {
                    start_tvusec: 1,
                    ..current
                }
            ),),
            Err(WorkerProtocolError::InvalidIdentity)
        );
        assert_eq!(wait.children[&child.pid], child);

        assert_eq!(
            new_wait().reconcile_membership(
                &server,
                &[server.pid, child.pid, 45],
                &leader,
                &[],
                &mut None,
                |pid| {
                    if pid == child.pid {
                        Err(std::io::Error::from_raw_os_error(libc::ESRCH))
                    } else {
                        Ok(crate::darwin::BsdProcessIdentity {
                            pid,
                            uid: 0,
                            ..current
                        })
                    }
                },
            ),
            Err(WorkerProtocolError::InvalidIdentity)
        );
    }

    #[cfg(target_os = "macos")]
    #[test]
    #[allow(
        clippy::zombie_processes,
        reason = "This fixture intentionally reparents children; the outer process verifies their kernel absence"
    )]
    fn startup_descendant_scopes_survive_reparenting_and_worker_loss() {
        const ROOT: &str = "DOLGORAE_TEST_STARTUP_SCOPE_ROOT";
        const ROLE: &str = "DOLGORAE_TEST_STARTUP_SCOPE_ROLE";
        const MODE: &str = "DOLGORAE_TEST_STARTUP_SCOPE_MODE";
        const NAME: &str =
            "worker::tests::startup_descendant_scopes_survive_reparenting_and_worker_loss";
        fn wait_for(root: &Path, name: &str) {
            let deadline = Instant::now() + Duration::from_secs(20);
            while !root.join(name).exists() {
                assert!(
                    Instant::now() < deadline,
                    "fixture timed out waiting for {name}"
                );
                thread::sleep(Duration::from_millis(10));
            }
        }
        fn command(root: &Path, role: &str) -> Command {
            let mut command = Command::new(std::env::current_exe().unwrap());
            command
                .args(["--exact", NAME, "--test-threads=1"])
                .env(ROOT, root)
                .env(ROLE, role)
                .env("HOME", root)
                .stdin(Stdio::null());
            command
        }
        fn pid(root: &Path, name: &str) -> u32 {
            wait_for(root, name);
            fs::read_to_string(root.join(name))
                .unwrap()
                .parse()
                .unwrap()
        }
        fn absent(pid: u32) {
            let deadline = Instant::now() + Duration::from_secs(5);
            loop {
                match DarwinSystem.bsd_process_identity(pid) {
                    Err(error) if error.raw_os_error() == Some(libc::ESRCH) => return,
                    Ok(_) if Instant::now() < deadline => thread::sleep(Duration::from_millis(10)),
                    other => panic!("fixture PID {pid} did not become absent: {other:?}"),
                }
            }
        }
        if let Some(root) = std::env::var_os(ROOT) {
            let root = PathBuf::from(root);
            match std::env::var(ROLE).unwrap().as_str() {
                "leaf" => {
                    fs::write(root.join("leaf.pid"), std::process::id().to_string()).unwrap();
                    wait_for(&root, "leaf.release");
                }
                "parent" => {
                    let _leaf = DarwinSystem
                        .spawn_detached(&mut command(&root, "leaf"))
                        .unwrap();
                    wait_for(&root, "leaf.pid");
                    fs::write(root.join("parent.pid"), std::process::id().to_string()).unwrap();
                    wait_for(&root, "parent.release");
                }
                "server" => {
                    let mut parent = command(&root, "parent").spawn().unwrap();
                    wait_for(&root, "parent.pid");
                    fs::write(root.join("server.ready"), b"ready").unwrap();
                    parent.wait().unwrap();
                    wait_for(&root, "server.release");
                }
                "worker" => {
                    let owner = current_startup_owner(&"11".repeat(32), Uuid::now_v7(), 1).unwrap();
                    let _server = DarwinSystem
                        .spawn_detached(&mut command(&root, "server"))
                        .unwrap();
                    let server_pid = _server.id();
                    wait_for(&root, "server.ready");
                    let leaf_pid = pid(&root, "leaf.pid");
                    let parent_pid = pid(&root, "parent.pid");
                    let process = DarwinSystem.bsd_process_identity(server_pid).unwrap();
                    let path = DarwinSystem.live_process_path(server_pid).unwrap();
                    let metadata = fs::metadata(&path).unwrap();
                    let server = DedicatedServerIdentity {
                        pid: process.pid,
                        uid: process.uid,
                        process_group_id: process.process_group_id,
                        session_id: process.session_id,
                        start_tvsec: process.start_tvsec,
                        start_tvusec: process.start_tvusec,
                        executable_device: metadata.dev(),
                        executable_inode: metadata.ino(),
                        executable_sha256: file_sha256(&path).unwrap(),
                        executable_path: path,
                    };
                    let socket_path =
                        dedicated_server_socket_path(owner.identity.uid, owner.identity.run_id, 1)
                            .unwrap();
                    prepare_socket_root(owner.identity.uid, socket_path.parent().unwrap()).unwrap();
                    let _socket = UnixListener::bind(&socket_path).unwrap();
                    let metadata = fs::symlink_metadata(&socket_path).unwrap();
                    let socket_identity = SocketIdentity {
                        device: metadata.dev(),
                        inode: metadata.ino(),
                    };
                    let mut witness = StartupScopeWitness::pending(owner.identity.clone(), 1);
                    witness.dedicated_server_identity = Some(server.clone());
                    witness.app_server_socket_identity = Some(socket_identity.clone());
                    let runtime = WorkerRuntimeRecord {
                        schema_version: 2,
                        socket_path: worker_socket_path(
                            owner.identity.uid,
                            &owner.identity.workspace_id,
                            owner.identity.run_id,
                        )
                        .unwrap(),
                        socket_identity: SocketIdentity {
                            device: 1,
                            inode: 1,
                        },
                        control_socket_epoch: 1,
                        app_server_epoch: Some(1),
                        control_recovery_required: false,
                        startup_scope: Some(witness),
                        dedicated_server_identity: Some(server.clone()),
                        dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
                        mutation_protocol_version: WORKER_PROTOCOL_VERSION,
                        binary_sha256: owner.identity.executable_sha256.clone(),
                        identity: owner.identity,
                    };
                    let runtime_path = root.join("runtime.json");
                    write_runtime_record(&runtime_path, &runtime).unwrap();
                    fs::write(
                        root.join("pending.json"),
                        serde_json::to_vec(&runtime).unwrap(),
                    )
                    .unwrap();
                    if std::env::var(MODE).unwrap() == "unobserved" {
                        fs::write(root.join("worker.kill-ready"), b"ready").unwrap();
                        wait_for(&root, "worker.release");
                        return;
                    }
                    let mut wait = StartupWorkload::new(
                        Duration::from_secs(10),
                        socket_path,
                        socket_identity,
                        runtime.identity.uid,
                    );
                    wait.runtime_path = Some(runtime_path.clone());
                    let census = DarwinSystem.all_process_identities().unwrap();
                    let leaf = census.iter().find(|entry| entry.pid == leaf_pid).unwrap();
                    assert_ne!(leaf.session_id, server.session_id);
                    assert_ne!(leaf.process_group_id, server.process_group_id);
                    DarwinSystem
                        .fixture_file_immutable(&runtime_path, true)
                        .unwrap();
                    let failed = wait.observe_owned(
                        leaf,
                        &server,
                        &census,
                        "fixture-write-failure",
                        &mut None,
                    );
                    DarwinSystem
                        .fixture_file_immutable(&runtime_path, false)
                        .unwrap();
                    assert_eq!(failed, Err(WorkerProtocolError::Io));
                    assert!(wait.children.is_empty());
                    assert!(
                        read_runtime_record(&runtime_path, runtime.identity.uid)
                            .unwrap()
                            .startup_scope
                            .unwrap()
                            .children
                            .is_empty()
                    );
                    wait.observe_owned(leaf, &server, &census, "fixture", &mut None)
                        .unwrap();
                    for observed in [
                        crate::darwin::ProcessCensusEntry {
                            uid: leaf.uid + 1,
                            ..*leaf
                        },
                        crate::darwin::ProcessCensusEntry {
                            birth: Some((leaf.birth.unwrap().0 + 1, 0)),
                            ..*leaf
                        },
                        crate::darwin::ProcessCensusEntry {
                            process_group_id: server.process_group_id,
                            ..*leaf
                        },
                        crate::darwin::ProcessCensusEntry {
                            session_id: server.session_id,
                            ..*leaf
                        },
                    ] {
                        assert_eq!(
                            wait.observe_owned(
                                &observed,
                                &server,
                                &census,
                                "fixture-negative",
                                &mut None
                            ),
                            Err(WorkerProtocolError::InvalidIdentity)
                        );
                    }
                    let worker_entry = census
                        .iter()
                        .find(|entry| entry.pid == runtime.identity.pid)
                        .unwrap();
                    assert_eq!(
                        wait.observe_owned(
                            worker_entry,
                            &server,
                            &census,
                            "fixture-unrelated",
                            &mut None
                        ),
                        Err(WorkerProtocolError::InvalidIdentity)
                    );
                    let mut reused = census.clone();
                    reused
                        .iter_mut()
                        .find(|entry| entry.pid == parent_pid)
                        .unwrap()
                        .birth = None;
                    assert!(startup_ancestry(&reused, leaf, &server).is_none());
                    let open = read_runtime_record(&runtime_path, runtime.identity.uid).unwrap();
                    assert_eq!(
                        open.startup_scope
                            .as_ref()
                            .unwrap()
                            .children
                            .iter()
                            .find(|child| child.identity.pid == leaf_pid)
                            .unwrap()
                            .identity,
                        *leaf
                    );
                    let mut corrupt = open.clone();
                    corrupt.startup_scope = None;
                    assert!(corrupt.validate().is_err());
                    corrupt = open.clone();
                    corrupt
                        .startup_scope
                        .as_mut()
                        .unwrap()
                        .worker_identity
                        .run_generation += 1;
                    assert!(write_runtime_record(&runtime_path, &corrupt).is_err());
                    corrupt = open.clone();
                    corrupt.startup_scope.as_mut().unwrap().children[0]
                        .ancestry
                        .clear();
                    assert!(write_runtime_record(&runtime_path, &corrupt).is_err());
                    let encoded = serde_json::to_value(&open).unwrap();
                    let mut frozen_v1 = encoded.clone();
                    frozen_v1.as_object_mut().unwrap().remove("startup_scope");
                    let frozen: WorkerRuntimeRecord =
                        serde_json::from_value(frozen_v1.clone()).unwrap();
                    assert!(
                        frozen.validate().is_err(),
                        "v2 cannot be accepted without ownership evidence"
                    );
                    frozen_v1["schema_version"] = serde_json::json!(1);
                    let frozen: WorkerRuntimeRecord =
                        serde_json::from_value(frozen_v1.clone()).unwrap();
                    frozen.validate().unwrap();
                    assert_eq!(serde_json::to_value(frozen).unwrap(), frozen_v1);
                    fs::write(root.join("open.json"), serde_json::to_vec(&open).unwrap()).unwrap();
                    assert!(
                        write_runtime_record(&runtime_path, &runtime).is_err(),
                        "stale startup copy must not erase a child"
                    );
                    fs::write(root.join("parent.release"), b"release").unwrap();
                    absent(parent_pid);
                    let deadline = Instant::now() + Duration::from_secs(5);
                    let mut reparented = DarwinSystem.bsd_process_identity(leaf_pid).unwrap();
                    while reparented.parent_pid == parent_pid {
                        assert!(Instant::now() < deadline, "fixture child did not reparent");
                        thread::sleep(Duration::from_millis(10));
                        reparented = DarwinSystem.bsd_process_identity(leaf_pid).unwrap();
                    }
                    assert_ne!(reparented.parent_pid, parent_pid);
                    let mut details = Value::Null;
                    assert_eq!(
                        prove_group_empty_observed(&open, true, false, Some(&mut details)),
                        Err(WorkerProtocolError::InvalidIdentity)
                    );
                    assert_eq!(details["predicate"], "startup_owned_child_live");
                    if std::env::var(MODE).unwrap() == "interrupted" {
                        fs::write(root.join("worker.kill-ready"), b"ready").unwrap();
                        wait_for(&root, "worker.release");
                        return;
                    }
                    fs::write(root.join("leaf.release"), b"release").unwrap();
                    absent(leaf_pid);
                    prove_group_empty_samples(
                        &open,
                        true,
                        false,
                        Some(&mut details),
                        Some(&mut wait),
                    )
                    .unwrap_or_else(|error| panic!("startup fixture proof: {error:?}; {details}"));
                    let completed =
                        update_runtime_record(&runtime_path, runtime.identity.uid, |record| {
                            let scope = record.startup_scope.as_mut().unwrap();
                            scope.complete = true;
                            scope.revision += 1;
                            Ok(())
                        })
                        .unwrap();
                    prove_worker_workload_absent(&completed).unwrap();
                    let mut same_epoch = completed.clone();
                    same_epoch.socket_identity.inode += 1;
                    assert!(write_runtime_record(&runtime_path, &same_epoch).is_err());
                    let mut replacement = completed.clone();
                    replacement.control_socket_epoch += 1;
                    replacement.socket_identity.inode += 1;
                    write_runtime_record(&runtime_path, &replacement).unwrap();
                    assert_eq!(
                        read_runtime_record(&runtime_path, runtime.identity.uid)
                            .unwrap()
                            .startup_scope,
                        completed.startup_scope
                    );
                    thread::scope(|scope| {
                        for _ in 0..2 {
                            scope.spawn(|| {
                                for _ in 0..3 {
                                    update_runtime_record(
                                        &runtime_path,
                                        runtime.identity.uid,
                                        |record| {
                                            record.control_socket_epoch += 1;
                                            record.socket_identity.inode += 1;
                                            Ok(())
                                        },
                                    )
                                    .unwrap();
                                }
                            });
                        }
                    });
                    let latest = read_runtime_record(&runtime_path, runtime.identity.uid).unwrap();
                    assert_eq!(
                        latest.control_socket_epoch,
                        completed.control_socket_epoch + 7
                    );
                    assert_eq!(latest.startup_scope, completed.startup_scope);
                    assert!(
                        write_runtime_record(&runtime_path, &completed).is_err(),
                        "stale locator epoch must be refused"
                    );
                }
                other => panic!("unknown fixture role {other}"),
            }
            return;
        }
        for mode in ["complete", "unobserved", "interrupted"] {
            let root = std::env::temp_dir().join(format!("dsw-{}", Uuid::now_v7().simple()));
            fs::DirBuilder::new().mode(0o700).create(&root).unwrap();
            let mut worker = DarwinSystem
                .spawn_detached(command(&root, "worker").env(MODE, mode))
                .unwrap();
            if mode == "complete" {
                assert!(worker.wait().unwrap().success());
            } else {
                wait_for(&root, "worker.kill-ready");
                worker.kill().unwrap();
                assert!(!worker.wait().unwrap().success());
            }
            let completed =
                read_runtime_record(&root.join("runtime.json"), DarwinSystem.current_uid())
                    .unwrap();
            let remove_fixture_socket = || {
                let identity = &completed.identity;
                let path = dedicated_server_socket_path(
                    identity.uid,
                    identity.run_id,
                    identity.run_generation,
                )
                .unwrap();
                let socket = completed
                    .startup_scope
                    .as_ref()
                    .unwrap()
                    .app_server_socket_identity
                    .as_ref()
                    .unwrap();
                crate::codex_socket::remove_recorded(
                    &path,
                    identity.uid,
                    socket.device,
                    socket.inode,
                )
                .unwrap();
            };
            if mode != "complete" {
                assert!(!completed.startup_scope.as_ref().unwrap().complete);
                assert_eq!(
                    completed
                        .startup_scope
                        .as_ref()
                        .unwrap()
                        .children
                        .is_empty(),
                    mode == "unobserved"
                );
                assert!(prove_worker_generation_absent(&completed).is_err());
                assert!(
                    remove_verified_absent_runtime(
                        &root.join("runtime.json"),
                        DarwinSystem.current_uid()
                    )
                    .is_err()
                );
                assert_eq!(
                    read_runtime_record(&root.join("runtime.json"), DarwinSystem.current_uid())
                        .unwrap(),
                    completed
                );
                fs::write(root.join("parent.release"), b"release").unwrap();
                fs::write(root.join("leaf.release"), b"release").unwrap();
                absent(pid(&root, "parent.pid"));
                absent(pid(&root, "leaf.pid"));
                fs::write(root.join("server.release"), b"release").unwrap();
                absent(completed.dedicated_server_identity.as_ref().unwrap().pid);
                assert!(prove_worker_generation_absent(&completed).is_err());
                remove_fixture_socket();
                fs::remove_dir_all(root).unwrap();
                continue;
            }
            for name in ["pending.json", "open.json"] {
                let interrupted: WorkerRuntimeRecord =
                    serde_json::from_slice(&fs::read(root.join(name)).unwrap()).unwrap();
                let mut details = Value::Null;
                assert_eq!(
                    prove_group_empty_observed(&interrupted, false, false, Some(&mut details)),
                    Err(WorkerProtocolError::InvalidIdentity)
                );
                assert_eq!(details["predicate"], "startup_ownership_incomplete");
            }
            fs::write(root.join("server.release"), b"release").unwrap();
            absent(completed.dedicated_server_identity.as_ref().unwrap().pid);
            let mut diagnostic = Value::Null;
            prove_group_empty_observed(&completed, false, false, Some(&mut diagnostic))
                .unwrap_or_else(|error| {
                    panic!("generation absence refused: {error:?}: {diagnostic}")
                });
            remove_fixture_socket();
            fs::remove_dir_all(root).unwrap();
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn workload_absence_can_be_proved_inside_a_detached_worker_with_owned_server() {
        const CHILD_ROOT: &str = "DOLGORAE_TEST_SELF_CENSUS_ROOT";
        if let Some(root) = std::env::var_os(CHILD_ROOT) {
            let root = PathBuf::from(root);
            let owner = current_startup_owner(&"11".repeat(32), Uuid::now_v7(), 1).unwrap();
            let identity = owner.identity;
            assert_eq!(identity.pid, identity.process_group_id);
            let mut command = Command::new("/bin/sh");
            command
                .args([
                    "-c",
                    "printf 'ready\\n'; while read launch; do [ \"$launch\" = shutdown ] && break; /bin/sh -c 'read release; /bin/sleep 0.6' <&0 & printf '%s\\n' \"$!\"; wait; done",
                ])
                .stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::null());
            let mut server = DarwinSystem.spawn_detached(&mut command).unwrap();
            let mut server_output = BufReader::new(server.stdout.take().unwrap());
            let mut readiness = String::new();
            server_output.read_line(&mut readiness).unwrap();
            assert_eq!(readiness, "ready\n");
            let process = DarwinSystem.bsd_process_identity(server.id()).unwrap();
            let path = DarwinSystem.live_process_path(server.id()).unwrap();
            let metadata = fs::metadata(&path).unwrap();
            let record = WorkerRuntimeRecord {
                schema_version: 1,
                socket_path: worker_socket_path(
                    identity.uid,
                    &identity.workspace_id,
                    identity.run_id,
                )
                .unwrap(),
                socket_identity: SocketIdentity {
                    device: 1,
                    inode: 1,
                },
                control_socket_epoch: 1,
                app_server_epoch: Some(1),
                control_recovery_required: false,
                startup_scope: None,
                dedicated_server_identity: Some(DedicatedServerIdentity {
                    pid: process.pid,
                    process_group_id: process.process_group_id,
                    session_id: process.session_id,
                    uid: process.uid,
                    start_tvsec: process.start_tvsec,
                    start_tvusec: process.start_tvusec,
                    executable_device: metadata.dev(),
                    executable_inode: metadata.ino(),
                    executable_sha256: file_sha256(&path).unwrap(),
                    executable_path: path,
                }),
                dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
                mutation_protocol_version: WORKER_PROTOCOL_VERSION,
                binary_sha256: identity.executable_sha256.clone(),
                identity,
            };
            let socket_path = root.join("s");
            let socket = UnixListener::bind(&socket_path).unwrap();
            let metadata = fs::symlink_metadata(&socket_path).unwrap();
            let mut startup = StartupWorkload::new(
                Duration::from_secs(10),
                socket_path.clone(),
                SocketIdentity {
                    device: metadata.dev(),
                    inode: metadata.ino(),
                },
                record.identity.uid,
            );
            let deadline = startup.deadline;
            let mut initial_details = Value::Null;
            let initial = prove_group_empty_samples(
                &record,
                true,
                false,
                Some(&mut initial_details),
                Some(&mut startup),
            );
            assert!(initial.is_ok(), "{initial:?}: {initial_details}");
            assert!(startup.children.is_empty());
            server.stdin.as_mut().unwrap().write_all(b"go\n").unwrap();
            let mut child_pid = String::new();
            server_output.read_line(&mut child_pid).unwrap();
            let child_pid = child_pid.trim().parse::<u32>().unwrap();
            let observed = DarwinSystem.bsd_process_identity(child_pid).unwrap();
            startup
                .observe(
                    &crate::darwin::ProcessCensusEntry {
                        pid: observed.pid,
                        parent_pid: observed.parent_pid,
                        uid: observed.uid,
                        process_group_id: observed.process_group_id,
                        session_id: observed.session_id,
                        birth: Some((observed.start_tvsec, observed.start_tvusec)),
                        zombie: observed.zombie,
                    },
                    record.dedicated_server_identity.as_ref().unwrap(),
                    &mut None,
                )
                .unwrap();
            assert_eq!(
                prove_worker_workload_absent(&record),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            let mut refusal = Value::Null;
            assert_eq!(
                prove_group_empty_observed(&record, true, false, Some(&mut refusal)),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(refusal["predicate"], "dedicated_scope");
            assert_eq!(refusal["observation"]["pid"], child_pid);
            // Exercise the policy-only census with a retained live process
            // witness. Production creates this witness only after exact-pair
            // admission; generic workload inspection above remains strict.
            let census = DarwinSystem.all_process_identities().unwrap();
            let child = *census.iter().find(|p| p.pid == child_pid).unwrap();
            let host = retirement_process(child, vec![child]).unwrap();
            let evidence = prove_group_empty_samples_with_companion(
                &record,
                true,
                false,
                None,
                None,
                Some(&host),
                false,
            )
            .unwrap();
            assert_eq!(evidence.consecutive_empty_samples, 5);
            assert!(prove_worker_workload_absent(&record).is_err());
            let mut drifted = host.clone();
            drifted.identity.birth = Some((0, 0));
            assert!(
                prove_group_empty_samples_with_companion(
                    &record,
                    true,
                    false,
                    None,
                    None,
                    Some(&drifted),
                    false,
                )
                .is_err()
            );
            let mut reparented = host.clone();
            reparented.identity.parent_pid += 1;
            assert!(
                prove_group_empty_samples_with_companion(
                    &record,
                    true,
                    false,
                    None,
                    None,
                    Some(&reparented),
                    false,
                )
                .is_err()
            );
            server
                .stdin
                .as_mut()
                .unwrap()
                .write_all(b"release\n")
                .unwrap();
            let mut details = Value::Null;
            let result = prove_group_empty_samples(
                &record,
                true,
                false,
                Some(&mut details),
                Some(&mut startup),
            );
            assert!(result.is_ok(), "{result:?}: {details}");
            assert!(startup.children.contains_key(&child_pid));
            assert!(startup.children_absent(&mut None).unwrap());
            assert!(prove_worker_workload_absent(&record).is_ok());
            let repeated = prove_group_empty_samples(
                &record,
                true,
                false,
                Some(&mut details),
                Some(&mut startup),
            );
            assert!(repeated.is_ok(), "{repeated:?}: {details}");
            assert_eq!(startup.deadline, deadline);
            // Once the connection window closes, the same real server's next
            // held child is an immediate refusal, even with startup time left.
            server.stdin.as_mut().unwrap().write_all(b"go\n").unwrap();
            let mut later_child_pid = String::new();
            server_output.read_line(&mut later_child_pid).unwrap();
            let later_child_pid = later_child_pid.trim().parse::<u32>().unwrap();
            assert_eq!(
                prove_group_empty_samples(&record, true, false, Some(&mut details), None),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(details["predicate"], "dedicated_scope");
            assert_eq!(details["observation"]["pid"], later_child_pid);
            assert!(!startup.children.contains_key(&later_child_pid));
            assert_eq!(startup.deadline, deadline);
            server
                .stdin
                .as_mut()
                .unwrap()
                .write_all(b"release\n")
                .unwrap();
            loop {
                match DarwinSystem.bsd_process_identity(later_child_pid) {
                    Err(error) if error.raw_os_error() == Some(libc::ESRCH) => break,
                    Ok(_) if Instant::now() < deadline => {
                        thread::sleep(Duration::from_millis(10));
                    }
                    other => panic!("later child did not become kernel-absent: {other:?}"),
                }
            }
            let proof = prove_group_empty_observed(&record, true, false, Some(&mut details));
            assert!(proof.is_ok(), "strict fixture proof: {proof:?}; {details}");
            startup.deadline = Instant::now();
            assert_eq!(
                prove_group_empty_samples(
                    &record,
                    true,
                    false,
                    Some(&mut details),
                    Some(&mut startup)
                ),
                Err(WorkerProtocolError::StartupQuiescenceTimeout)
            );
            assert_eq!(details["predicate"], "startup_quiescence_timeout");
            let observation = &details["observation"];
            assert_eq!(observation["site"], "before_sample");
            assert_eq!(observation["sampled_count"], 0);
            assert_eq!(observation["consecutive_empty_samples"], 0);
            assert!(observation["deadline_overrun_ms"].is_u64());
            assert_eq!(observation["proof_entry_remaining_ms"], 0);
            assert_eq!(observation["remaining_budget_at_sample_start_ms"], 0);
            assert!(observation["sample_elapsed_ms"].is_null());
            assert_eq!(observation["retained_child_count"], startup.children.len());
            assert!(
                observation["retained_child_sample"]
                    .as_array()
                    .unwrap()
                    .len()
                    <= 4
            );
            assert!(observation["last_sample"].is_null());
            let runtime_path = root.join("context-runtime.json");
            let mut context_record = record.clone();
            context_record.schema_version = 2;
            let mut witness = StartupScopeWitness::pending(record.identity.clone(), 1);
            witness.dedicated_server_identity = record.dedicated_server_identity.clone();
            witness.app_server_socket_identity = Some(startup.socket_identity.clone());
            witness.complete = false;
            context_record.startup_scope = Some(witness);
            write_runtime_record(&runtime_path, &context_record).unwrap();
            let mut expired = StartupWorkload::new(
                Duration::ZERO,
                socket_path.clone(),
                startup.socket_identity.clone(),
                record.identity.uid,
            );
            expired.deadline = startup.deadline;
            let mut commit = QualifiedCallerRuntime {
                runtime: context_record.clone(),
                runtime_path: runtime_path.clone(),
                socket_path: socket_path.clone(),
                socket_identity: startup.socket_identity.clone(),
                server_key: "test".to_owned(),
                binding_sha256: "1".repeat(64),
                startup: Some(expired),
            };
            let before_commit = fs::read(&runtime_path).unwrap();
            let mut commit_details = Value::Null;
            assert_eq!(
                commit.complete_startup_witness(Some(&mut commit_details)),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(commit_details["predicate"], "startup_commit_timeout");
            assert_eq!(commit_details["observation"]["site"], "before_final_proof");
            assert_eq!(
                commit_details["observation"]["remaining_budget_before_final_proof_ms"],
                0
            );
            assert!(commit_details["observation"]["final_proof_elapsed_ms"].is_null());
            assert!(commit_details["observation"]["deadline_overrun_ms"].is_u64());
            assert!(commit.startup.is_none());
            assert_eq!(fs::read(&runtime_path).unwrap(), before_commit);
            assert!(
                !read_runtime_record(&runtime_path, record.identity.uid)
                    .unwrap()
                    .startup_scope
                    .unwrap()
                    .complete
            );
            crate::turn::tests::assert_startup_process_context(QualifiedCallerRuntime {
                runtime: context_record,
                runtime_path,
                socket_path: socket_path.clone(),
                socket_identity: startup.socket_identity.clone(),
                server_key: "test".to_owned(),
                binding_sha256: "1".repeat(64),
                startup: Some(StartupWorkload::new(
                    Duration::ZERO,
                    socket_path.clone(),
                    startup.socket_identity.clone(),
                    record.identity.uid,
                )),
            });

            assert!(prove_worker_workload_absent(&record).is_ok());
            startup.deadline = Instant::now() + Duration::from_secs(1);
            fs::remove_file(&socket_path).unwrap();
            assert_eq!(
                prove_group_empty_samples(
                    &record,
                    true,
                    false,
                    Some(&mut details),
                    Some(&mut startup)
                ),
                Err(WorkerProtocolError::SocketIdentityMismatch)
            );
            assert_eq!(details["predicate"], "app_server_socket_identity");
            assert_eq!(
                details["observation"]["expected_identity"]["device"],
                metadata.dev()
            );
            assert_eq!(
                details["observation"]["expected_identity"]["inode"],
                metadata.ino()
            );
            drop(socket);
            let diagnostic = serde_json::json!({
                "worker": classify_worker_identity(&record).as_str(),
                "server": classify_dedicated_server_identity(record.dedicated_server_identity.as_ref().unwrap()).as_str(),
                "result": format!("{result:?}"),
            });
            let mut proof_file = OpenOptions::new()
                .write(true)
                .create_new(true)
                .mode(0o600)
                .open(root.join("proof.json"))
                .unwrap();
            proof_file
                .write_all(&serde_json::to_vec(&diagnostic).unwrap())
                .unwrap();
            assert_eq!(
                classify_dedicated_server_identity(
                    record.dedicated_server_identity.as_ref().unwrap()
                ),
                ProcessIdentityVerdict::Match
            );
            DarwinSystem
                .signal_process_group(server.id(), libc::SIGTERM)
                .unwrap();
            server.wait().unwrap();
            assert!(result.is_ok(), "{diagnostic}");
            return;
        }
        let root = std::env::temp_dir().join(format!("dqs-{}", Uuid::now_v7().simple()));
        fs::DirBuilder::new().mode(0o700).create(&root).unwrap();
        let mut command = Command::new(std::env::current_exe().unwrap());
        command.args(["--exact", "worker::tests::workload_absence_can_be_proved_inside_a_detached_worker_with_owned_server", "--test-threads=1"])
            .env(CHILD_ROOT, &root).env("HOME", &root).stdin(Stdio::null());
        let mut child = DarwinSystem.spawn_detached(&mut command).unwrap();
        let status = child.wait().unwrap();
        let diagnostic = fs::read_to_string(root.join("proof.json")).unwrap();
        fs::remove_dir_all(root).unwrap();
        assert!(status.success(), "{diagnostic}");
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn dedicated_server_does_not_hide_worker_group_workload() {
        fn executable_identity(path: &Path) -> (PathBuf, u64, u64, String) {
            let path = DarwinSystem.realpath(path).unwrap();
            let metadata = fs::metadata(&path).unwrap();
            let digest = file_sha256(&path).unwrap();
            (path, metadata.dev(), metadata.ino(), digest)
        }

        let mut worker_command = Command::new("/bin/sh");
        worker_command
            .args(["-c", "sleep 30 & wait"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut worker = DarwinSystem.spawn_detached(&mut worker_command).unwrap();
        let mut server_command = Command::new("/bin/sleep");
        server_command
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut server = DarwinSystem.spawn_detached(&mut server_command).unwrap();
        std::thread::sleep(Duration::from_millis(100));

        let worker_process = DarwinSystem.bsd_process_identity(worker.id()).unwrap();
        let server_process = DarwinSystem.bsd_process_identity(server.id()).unwrap();
        let (worker_path, worker_device, worker_inode, worker_digest) =
            executable_identity(&DarwinSystem.live_process_path(worker.id()).unwrap());
        let (server_path, server_device, server_inode, server_digest) =
            executable_identity(Path::new("/bin/sleep"));
        let identity = WorkerIdentity {
            workspace_id: "11".repeat(32),
            run_id: Uuid::now_v7(),
            run_generation: 1,
            boot_uuid: Uuid::parse_str(&DarwinSystem.boot_session_uuid().unwrap()).unwrap(),
            pid: worker_process.pid,
            process_group_id: worker_process.process_group_id,
            session_id: worker_process.session_id,
            uid: worker_process.uid,
            start_tvsec: worker_process.start_tvsec,
            start_tvusec: worker_process.start_tvusec,
            executable_path: worker_path,
            executable_device: worker_device,
            executable_inode: worker_inode,
            executable_sha256: worker_digest,
        };
        let record = WorkerRuntimeRecord {
            schema_version: 1,
            socket_path: worker_socket_path(identity.uid, &identity.workspace_id, identity.run_id)
                .unwrap(),
            identity,
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: Some(1),
            control_recovery_required: false,
            startup_scope: None,
            dedicated_server_identity: Some(DedicatedServerIdentity {
                pid: server_process.pid,
                process_group_id: server_process.process_group_id,
                session_id: server_process.session_id,
                uid: server_process.uid,
                start_tvsec: server_process.start_tvsec,
                start_tvusec: server_process.start_tvusec,
                executable_path: server_path,
                executable_device: server_device,
                executable_inode: server_inode,
                executable_sha256: server_digest,
            }),
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: current_dolgorae_build().unwrap().binary_sha256,
        };

        let checked = std::panic::catch_unwind(|| {
            assert_eq!(
                classify_worker_identity(&record),
                ProcessIdentityVerdict::Match
            );
            assert_eq!(
                classify_dedicated_server_identity(
                    record.dedicated_server_identity.as_ref().unwrap()
                ),
                ProcessIdentityVerdict::Match
            );
            assert_eq!(
                prove_worker_workload_absent(&record),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            let mut diagnostic = Value::Null;
            assert_eq!(
                prove_group_empty_observed(&record, true, false, Some(&mut diagnostic)),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(diagnostic["predicate"], "worker_scope");
            assert_ne!(diagnostic["observation"]["pid"], record.identity.pid);
        });

        let _ = DarwinSystem.signal_process_group(worker.id(), libc::SIGKILL);
        let _ = DarwinSystem.signal_process_group(server.id(), libc::SIGKILL);
        let _ = worker.wait();
        let _ = server.wait();
        if let Err(error) = checked {
            std::panic::resume_unwind(error);
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn killed_unpublished_dedicated_server_releases_its_exact_socket() {
        let uid = DarwinSystem.current_uid();
        let owner = fs::canonicalize("/tmp")
            .unwrap()
            .join(format!("dolgorae-unpublished-{}", Uuid::now_v7()));
        fs::create_dir(&owner).unwrap();
        let socket_parent = PathBuf::from(format!("/tmp/dolgorae-{uid}/c"));
        prepare_socket_root(uid, &socket_parent).unwrap();
        let socket = socket_parent.join(format!("{}.sock", Uuid::now_v7()));
        crate::codex_socket::require_vacant(&socket, uid).unwrap();
        let protected = fs::canonicalize("/tmp")
            .unwrap()
            .join(format!("codex-daemon-{uid}"));
        match fs::DirBuilder::new().mode(0o700).create(&protected) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(error) => panic!("protected test directory: {error}"),
        }
        let canonical = fs::canonicalize(&socket_parent)
            .unwrap()
            .join(socket.file_name().unwrap());
        let target = protected.join(format!(
            "{:x}",
            Sha256::digest(canonical.as_os_str().as_encoded_bytes())
        ));
        let mut registration = crate::process_inventory::Registration::prepare(
            "dedicated_server",
            &owner,
            Path::new("/bin/sleep"),
            format!("unix://{}", socket.display()),
            Some(&socket),
            Some("default"),
            Some(Uuid::now_v7()),
        )
        .unwrap();
        let mut command = Command::new("/bin/sleep");
        command
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut child = DarwinSystem.spawn_detached(&mut command).unwrap();
        registration.mark_spawned(child.id());
        let listener = UnixListener::bind(&target).unwrap();
        fs::set_permissions(&target, fs::Permissions::from_mode(0o600)).unwrap();
        std::os::unix::fs::symlink(&target, &socket).unwrap();
        drop(listener);
        DarwinSystem
            .signal_process_group(child.id(), libc::SIGKILL)
            .unwrap();
        terminate_unpublished_child(&mut child, &mut registration, &socket);
        assert!(fs::symlink_metadata(&socket).is_err());
        assert!(fs::symlink_metadata(&target).is_err());
        crate::codex_socket::require_vacant(&socket, uid).unwrap();
        fs::remove_dir(owner).unwrap();
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn dedicated_stop_scope_requires_complete_census_and_owned_descendants() {
        let server = DedicatedServerIdentity {
            pid: 42,
            process_group_id: 42,
            session_id: 42,
            uid: 501,
            start_tvsec: 10,
            start_tvusec: 20,
            executable_path: PathBuf::from("/bin/server"),
            executable_device: 1,
            executable_inode: 2,
            executable_sha256: "11".repeat(32),
        };
        let leader = crate::darwin::ProcessCensusEntry {
            pid: 42,
            parent_pid: 1,
            uid: 501,
            process_group_id: 42,
            session_id: 42,
            birth: Some((10, 20)),
            zombie: false,
        };
        let helper = crate::darwin::ProcessCensusEntry {
            pid: 43,
            parent_pid: 42,
            process_group_id: 43,
            birth: Some((11, 20)),
            ..leader
        };
        let descendant = crate::darwin::ProcessCensusEntry {
            pid: 44,
            parent_pid: 43,
            process_group_id: 44,
            session_id: 44,
            ..helper
        };
        let census = [leader, helper, descendant];
        assert!(dedicated_scope_is_owned(&server, &[42], &census));
        assert!(!dedicated_scope_is_owned(&server, &[], &census));
        assert!(!dedicated_scope_is_owned(&server, &[42, 43], &census));
        for index in 0..census.len() {
            let mut foreign = census;
            foreign[index].uid = 502;
            assert!(!dedicated_scope_is_owned(&server, &[42], &foreign));
        }
        let mut reused = census;
        reused[0].birth = Some((10, 21));
        assert!(!dedicated_scope_is_owned(&server, &[42], &reused));
        let mut missing_birth = census;
        missing_birth[0].birth = None;
        assert!(!dedicated_scope_is_owned(&server, &[42], &missing_birth));
        assert!(!dedicated_scope_is_owned(
            &server,
            &[],
            &[helper, descendant]
        ));
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn dedicated_absence_still_refuses_a_surviving_separate_group_helper() {
        let mut command = Command::new("/bin/sh");
        command
            .args(["-c", "set -m; sleep 2 & wait"])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut server = DarwinSystem.spawn_detached(&mut command).unwrap();
        std::thread::sleep(Duration::from_millis(100));
        let observed = DarwinSystem.bsd_process_identity(server.id()).unwrap();
        let executable_path = DarwinSystem.realpath(Path::new("/bin/sh")).unwrap();
        let metadata = fs::metadata(&executable_path).unwrap();
        let identity = DedicatedServerIdentity {
            pid: observed.pid,
            process_group_id: observed.process_group_id,
            session_id: observed.session_id,
            uid: observed.uid,
            start_tvsec: observed.start_tvsec,
            start_tvusec: observed.start_tvusec,
            executable_path: executable_path.clone(),
            executable_device: metadata.dev(),
            executable_inode: metadata.ino(),
            executable_sha256: file_sha256(&executable_path).unwrap(),
        };
        let checked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            assert!(dedicated_group_safe_to_signal(&identity));
            DarwinSystem
                .signal_process_group(identity.process_group_id, libc::SIGTERM)
                .unwrap();
            server.wait().unwrap();
            assert_eq!(
                classify_dedicated_server_identity(&identity),
                ProcessIdentityVerdict::Absent
            );
            assert!(!dedicated_group_has_only_expected_leader(&identity, false).unwrap());
            let deadline = Instant::now() + Duration::from_secs(5);
            while Instant::now() < deadline
                && !dedicated_group_has_only_expected_leader(&identity, false).unwrap()
            {
                std::thread::sleep(Duration::from_millis(100));
            }
            assert!(dedicated_group_has_only_expected_leader(&identity, false).unwrap());
        }));
        if classify_dedicated_server_identity(&identity) == ProcessIdentityVerdict::Match {
            let _ = DarwinSystem.signal_process_group(server.id(), libc::SIGTERM);
        }
        let _ = server.wait();
        if let Err(error) = checked {
            std::panic::resume_unwind(error);
        }
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn an_orphaned_dedicated_server_is_retired_only_after_worker_absence() {
        let mut worker_command = Command::new("/bin/sleep");
        worker_command
            .arg("30")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut worker = DarwinSystem.spawn_detached(&mut worker_command).unwrap();
        let mut server_command = Command::new("/bin/sh");
        server_command
            .args([
                "-c",
                "set -m; trap 'kill -TERM \"$helper\"; wait \"$helper\"; exit 0' TERM; sleep 30 & helper=$!; wait \"$helper\"",
            ])
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        let mut server = DarwinSystem.spawn_detached(&mut server_command).unwrap();
        std::thread::sleep(Duration::from_millis(100));

        let worker_observed = DarwinSystem.bsd_process_identity(worker.id()).unwrap();
        let observed = DarwinSystem.bsd_process_identity(server.id()).unwrap();
        let executable_path = DarwinSystem.realpath(Path::new("/bin/sleep")).unwrap();
        let metadata = fs::metadata(&executable_path).unwrap();
        let server_executable = DarwinSystem
            .realpath(&DarwinSystem.live_process_path(server.id()).unwrap())
            .unwrap();
        let server_metadata = fs::metadata(&server_executable).unwrap();
        let server_identity = DedicatedServerIdentity {
            pid: observed.pid,
            process_group_id: observed.process_group_id,
            session_id: observed.session_id,
            uid: observed.uid,
            start_tvsec: observed.start_tvsec,
            start_tvusec: observed.start_tvusec,
            executable_path: server_executable.clone(),
            executable_device: server_metadata.dev(),
            executable_inode: server_metadata.ino(),
            executable_sha256: file_sha256(&server_executable).unwrap(),
        };
        let current = DarwinSystem.current_process().unwrap();
        let workspace_id = "11".repeat(32);
        let run_id = Uuid::now_v7();
        let record = WorkerRuntimeRecord {
            schema_version: 1,
            socket_path: worker_socket_path(current.uid, &workspace_id, run_id).unwrap(),
            identity: WorkerIdentity {
                workspace_id,
                run_id,
                run_generation: 1,
                boot_uuid: boot_session_uuid(current.uid).unwrap(),
                pid: worker_observed.pid,
                process_group_id: worker_observed.process_group_id,
                session_id: worker_observed.session_id,
                uid: worker_observed.uid,
                start_tvsec: worker_observed.start_tvsec,
                start_tvusec: worker_observed.start_tvusec,
                executable_path: executable_path.clone(),
                executable_device: metadata.dev(),
                executable_inode: metadata.ino(),
                executable_sha256: file_sha256(&executable_path).unwrap(),
            },
            socket_identity: SocketIdentity {
                device: 1,
                inode: 1,
            },
            control_socket_epoch: 1,
            app_server_epoch: Some(1),
            control_recovery_required: false,
            startup_scope: None,
            dedicated_server_identity: Some(server_identity.clone()),
            dolgorae_version: env!("CARGO_PKG_VERSION").to_owned(),
            mutation_protocol_version: WORKER_PROTOCOL_VERSION,
            binary_sha256: current_dolgorae_build().unwrap().binary_sha256,
        };

        let checked = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let census = DarwinSystem.all_process_identities().unwrap();
            assert!(census.iter().any(|process| {
                process.parent_pid == server_identity.pid
                    && process.session_id == server_identity.session_id
                    && process.process_group_id != server_identity.process_group_id
            }));
            assert!(!dedicated_group_has_only_expected_leader(&server_identity, true).unwrap());
            let mut diagnostic = Value::Null;
            assert!(
                !dedicated_group_has_only_expected_leader_observed(
                    &server_identity,
                    true,
                    Some(&mut diagnostic)
                )
                .unwrap()
            );
            assert_eq!(diagnostic["predicate"], "dedicated_scope");
            assert_ne!(diagnostic["observation"]["pid"], server_identity.pid);
            assert!(dedicated_group_safe_to_signal(&server_identity));
            assert_eq!(
                classify_worker_identity(&record),
                ProcessIdentityVerdict::Match
            );
            assert_eq!(
                stop_orphaned_dedicated_server(&record),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(
                classify_dedicated_server_identity(&server_identity),
                ProcessIdentityVerdict::Match
            );

            DarwinSystem
                .signal_process_group(worker.id(), libc::SIGKILL)
                .unwrap();
            worker.wait().unwrap();
            assert_eq!(
                classify_worker_identity(&record),
                ProcessIdentityVerdict::Absent
            );
            assert!(prove_group_empty(&record, false, true).is_ok());
            // The dedicated leader survives Worker loss: writer retirement's
            // complete-generation proof cannot run before guarded cleanup.
            assert_eq!(
                prove_worker_generation_absent(&record),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            let mut mismatched = record.clone();
            mismatched
                .dedicated_server_identity
                .as_mut()
                .unwrap()
                .start_tvusec += 1;
            assert_eq!(
                stop_orphaned_dedicated_server(&mismatched),
                Err(WorkerProtocolError::InvalidIdentity)
            );
            assert_eq!(
                classify_dedicated_server_identity(&server_identity),
                ProcessIdentityVerdict::Match
            );
            stop_orphaned_dedicated_server(&record).unwrap();
            assert_eq!(
                classify_dedicated_server_identity(&server_identity),
                ProcessIdentityVerdict::Absent
            );
            assert_eq!(
                prove_worker_generation_absent(&record)
                    .unwrap()
                    .consecutive_empty_samples,
                5
            );
        }));
        if classify_worker_identity(&record) == ProcessIdentityVerdict::Match {
            let _ = DarwinSystem.signal_process_group(worker.id(), libc::SIGKILL);
        }
        if classify_dedicated_server_identity(&server_identity) == ProcessIdentityVerdict::Match {
            let _ = DarwinSystem.signal_process_group(server.id(), libc::SIGTERM);
        }
        let _ = worker.wait();
        let _ = server.wait();
        if let Err(error) = checked {
            std::panic::resume_unwind(error);
        }
    }

