    #[test]
    fn owner_slots_are_fixed_checked_and_zero_padded() {
        let record = StartupOwnerRecord {
            schema_version: 1,
            slot: 1,
            identity: identity(),
            executable_path_sha256: "55".repeat(32),
        };
        let encoded = record.encode_slot().unwrap();
        assert_eq!(encoded.len(), STARTUP_SLOT_BYTES);
        assert_eq!(
            StartupOwnerRecord::decode_slot(&encoded).unwrap(),
            Some(record)
        );
        let mut corrupt = encoded;
        corrupt[10] ^= 1;
        assert_eq!(
            StartupOwnerRecord::decode_slot(&corrupt),
            Err(WorkerProtocolError::InvalidOwnerRecord)
        );
        assert_eq!(
            StartupOwnerRecord::decode_slot(&[0; STARTUP_SLOT_BYTES]).unwrap(),
            None
        );
    }

    #[test]
    fn frozen_control_deadline_expires_despite_incomplete_response_trickling() {
        let (client, mut peer) = UnixStream::pair().unwrap();
        let started = std::time::Instant::now();
        let stream =
            DeadlineStream::from_connected(client, started + Duration::from_millis(100)).unwrap();
        let sender = thread::spawn(move || {
            for _ in 0..200 {
                if peer.write_all(b" ").is_err() {
                    break;
                }
                thread::sleep(Duration::from_millis(10));
            }
        });
        let mut reader = BufReader::new(stream);
        assert!(matches!(
            read_frame::<_, ControlResponseV1>(&mut reader),
            Err(WorkerProtocolError::Io)
        ));
        let elapsed = started.elapsed();
        drop(reader);
        sender.join().unwrap();
        assert!(
            elapsed < Duration::from_secs(1),
            "response chunks renewed the deadline: {elapsed:?}"
        );
    }

    #[test]
    fn frozen_control_deadline_connects_and_exchanges_checked_frames() {
        let root = std::env::temp_dir().join(format!("dc-{}", Uuid::now_v7().simple()));
        fs::create_dir(&root).unwrap();
        let path = root.join("s");
        let listener = UnixListener::bind(&path).unwrap();
        let expected = identity();
        let request = ControlRequestV1::Status {
            expected: expected.clone(),
        };
        let worker = thread::spawn(move || {
            let (stream, _) = listener.accept().unwrap();
            let mut reader = BufReader::new(stream);
            let request: ControlRequestV1 = read_frame(&mut reader).unwrap();
            assert!(matches!(request, ControlRequestV1::Status { .. }));
            assert_eq!(request.expected(), &expected);
            write_frame(
                reader.get_mut(),
                &ControlResponseV1::Status {
                    identity: expected,
                    lifecycle: "idle".to_owned(),
                    active_turn: None,
                    last_terminal: None,
                },
            )
            .unwrap();
        });
        let mut stream =
            DeadlineStream::connect(&path, std::time::Instant::now() + Duration::from_secs(2))
                .unwrap();
        write_frame(&mut stream, &request).unwrap();
        assert!(
            matches!(read_frame::<_, ControlResponseV1>(&mut BufReader::new(stream)).unwrap(), ControlResponseV1::Status { lifecycle, .. } if lifecycle == "idle")
        );
        worker.join().unwrap();
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn bounded_frames_recover_after_an_oversized_caller() {
        let mut wire = vec![b'x'; MAX_CLI_WORKER_FRAME_BYTES + 1];
        wire.extend_from_slice(b"\n{\"operation\":\"status\",\"expected\":");
        wire.extend_from_slice(&serde_json::to_vec(&identity()).unwrap());
        wire.extend_from_slice(b"}\n");
        let mut reader = BufReader::new(Cursor::new(wire));
        assert!(matches!(
            read_frame::<_, ControlRequestV1>(&mut reader),
            Err(WorkerProtocolError::FrameTooLarge { observed_bytes })
                if observed_bytes > MAX_CLI_WORKER_FRAME_BYTES as u64
        ));
        assert!(matches!(
            read_frame::<_, ControlRequestV1>(&mut reader).unwrap(),
            ControlRequestV1::Status { .. }
        ));
    }

